export const GUIDED: Record<string, GuidedLab> = {"labex-matplotlib-shade-regions-with-fill-between":{"intro":"In this lab, we will learn how to shade regions in a Matplotlib plot using the fill_between function. This is useful for highlighting specific areas of the plot, such as regions where a certain condition is met.","steps":[{"title":"Import Necessary Libraries","body":["We will start by importing the necessary libraries for this lab, which are numpy and matplotlib.pyplot."],"code":[{"lang":"python","text":"import numpy as np\nimport matplotlib.pyplot as plt"}]},{"title":"Create Data","body":["We will create some data to use for our plot. In this example, we will create a sine wave."],"code":[{"lang":"python","text":"t = np.arange(0.0, 2, 0.01)\ns = np.sin(2*np.pi*t)"}]},{"title":"Create the Plot","body":["Now we will create the plot using matplotlib.pyplot. We will plot the sine wave and add a horizontal line at y=0."],"code":[{"lang":"python","text":"fig, ax = plt.subplots()\n\nax.plot(t, s, color='black')\nax.axhline(0, color='black')"}]},{"title":"Shade the Regions","body":["We will use fill_between to shade the regions above and below the horizontal line where the sine wave is positive and negative, respectively."],"code":[{"lang":"python","text":"ax.fill_between(t, 1, where=s > 0, facecolor='green', alpha=.5)\nax.fill_between(t, -1, where=s < 0, facecolor='red', alpha=.5)"}]},{"title":"Show the Plot","body":["Finally, we will show the plot using plt.show()."],"code":[{"lang":"python","text":"plt.show()"}]}],"commands":[],"reference":[],"source":"matplotlib/matplotlib · BSD 3-Clause"},"labex-matplotlib-matplotlib-span-selector":{"intro":"This lab will guide you through how to use the Matplotlib Span Selector to select a range on an axis and plot a detailed view of the selected range on another axis.","steps":[{"title":"Import Required Libraries","body":["First, we need to import the required libraries - numpy and matplotlib."],"code":[{"lang":"python","text":"import numpy as np\nimport matplotlib.pyplot as plt"}]},{"title":"Create Sample Data","body":["We will now create some sample data to plot using numpy."],"code":[{"lang":"python","text":"# Fixing random state for reproducibility\nnp.random.seed(19680801)\n\nx = np.arange(0.0, 5.0, 0.01)\ny = np.sin(2 * np.pi * x) + 0.5 * np.random.randn(len(x))"}]},{"title":"Create Figure and Subplots","body":["We will now create a figure with two subplots using matplotlib."],"code":[{"lang":"python","text":"fig, (ax1, ax2) = plt.subplots(2, figsize=(8, 6))"}]},{"title":"Plot Data on First Subplot","body":["We will plot the sample data on the first subplot."],"code":[{"lang":"python","text":"ax1.plot(x, y)\nax1.set_ylim(-2, 2)\nax1.set_title('Press left mouse button and drag '\n              'to select a region in the top graph')"}]},{"title":"Define a Callback Function","body":["We will define a callback function that will be called when a range is selected using the Span Selector."],"code":[{"lang":"python","text":"def onselect(xmin, xmax):\n    indmin, indmax = np.searchsorted(x, (xmin, xmax))\n    indmax = min(len(x) - 1, indmax)\n\n    region_x = x[indmin:indmax]\n    region_y = y[indmin:indmax]\n\n    if len(region_x) >= 2:\n        line2.set_data(region_x, region_y)\n        ax2.set_xlim(region_x[0], region_x[-1])\n        ax2.set_ylim(region_y.min(), region_y.max())\n        fig.canvas.draw_idle()"}]},{"title":"Create a Span Selector","body":["We will create a Span Selector object using matplotlib.widgets.SpanSelector."],"code":[{"lang":"python","text":"span = SpanSelector(\n    ax1,\n    onselect,\n    \"horizontal\",\n    useblit=True,\n    props=dict(alpha=0.5, facecolor=\"tab:blue\"),\n    interactive=True,\n    drag_from_anywhere=True\n)"}]},{"title":"Plot Data on Second Subplot","body":["We will plot the detailed view of the selected range on the second subplot."],"code":[{"lang":"python","text":"line2, = ax2.plot([], [])"}]},{"title":"Show Plot","body":["We will now show the plot using matplotlib.pyplot.show()."],"code":[{"lang":"python","text":"plt.show()"}]}],"commands":[],"reference":[],"source":"matplotlib/matplotlib · BSD 3-Clause"},"labex-matplotlib-spectrogram-plotting-with-matplotlib":{"intro":"In this lab, we will learn how to create a spectrogram plot using Matplotlib. A spectrogram is a visual representation of the spectrum of frequencies of a signal as it varies with time. Spectrograms are commonly used to analyze the frequency content of a signal over time, such as in speech recognition, music analysis, and audio signal processing. We will use Python and Matplotlib to create a spectrogram plot of a signal.","steps":[{"title":"Import Libraries","body":["We will start by importing the necessary libraries: NumPy and Matplotlib."],"code":[{"lang":"python","text":"import matplotlib.pyplot as plt\nimport numpy as np"}]},{"title":"Generate Signal","body":["Next, we will generate a signal to plot. In this example, we will create a signal that is the sum of two sine waves with different frequencies, and some random noise."],"code":[{"lang":"python","text":"# Fixing random state for reproducibility\nnp.random.seed(19680801)\n\ndt = 0.0005\nt = np.arange(0.0, 20.0, dt)\ns1 = np.sin(2 * np.pi * 100 * t)\ns2 = 2 * np.sin(2 * np.pi * 400 * t)\n\n# create a transient \"chirp\"\ns2[t <= 10] = s2[12 <= t] = 0\n\n# add some noise into the mix\nnse = 0.01 * np.random.random(size=len(t))\n\nx = s1 + s2 + nse  # the signal"}]},{"title":"Generate Spectrogram","body":["Now we will generate a spectrogram plot of the signal. We will use the specgram method from Matplotlib's Axes class to generate the spectrogram. This method returns four objects: Pxx, freqs, bins, and im. Pxx is the periodogram, freqs is the frequency vector, bins is the centers of the time bins, and im is the AxesImage instance representing the data in the plot."],"code":[{"lang":"python","text":"NFFT = 1024  # the length of the windowing segments\nFs = int(1.0 / dt)  # the sampling frequency\n\nfig, (ax1, ax2) = plt.subplots(nrows=2)\nax1.plot(t, x)\nPxx, freqs, bins, im = ax2.specgram(x, NFFT=NFFT, Fs=Fs, noverlap=900)"}]},{"title":"Customize Plot","body":["We can customize the plot by adding titles, axis labels, and color maps."],"code":[{"lang":"python","text":"fig, (ax1, ax2) = plt.subplots(nrows=2)\nax1.set_title('Time Domain Signal')\nax1.set_xlabel('Time (s)')\nax1.set_ylabel('Amplitude')\nax1.plot(t, x)\n\nax2.set_title('Spectrogram')\nax2.set_xlabel('Time (s)')\nax2.set_ylabel('Frequency (Hz)')\nim = ax2.specgram(x, NFFT=NFFT, Fs=Fs, noverlap=900, cmap='viridis')\nfig.colorbar(im[3], ax=ax2)"}]},{"title":"Display Plot","body":["Finally, we will display the plot."],"code":[{"lang":"python","text":"plt.show()"}]}],"commands":[],"reference":[],"source":"matplotlib/matplotlib · BSD 3-Clause"},"labex-matplotlib-generating-and-visualizing-sine-signals-with":{"intro":"This lab will guide you through generating and visualizing a sine signal with additive noise using Python's Matplotlib library. Specifically, we will create different spectrum representations of the signal using the fast Fourier transform (FFT).","steps":[{"title":"Import necessary libraries","body":["First, we need to import the necessary libraries. We will be using NumPy and Matplotlib."],"code":[{"lang":"python","text":"import matplotlib.pyplot as plt\nimport numpy as np"}]},{"title":"Set up variables","body":["Next, we will set up the variables for our signal. We will use a sampling interval of 0.01, which gives us a sampling frequency of 100 Hz. We will create a time array from 0 to 10 seconds with a step of 0.01 seconds. We will also generate noise using NumPy's randn function and convolve it with an exponential decay function to create a noisy signal."],"code":[{"lang":"python","text":"np.random.seed(0)\n\ndt = 0.01  # sampling interval\nFs = 1 / dt  # sampling frequency\nt = np.arange(0, 10, dt)\n\n# generate noise:\nnse = np.random.randn(len(t))\nr = np.exp(-t / 0.05)\ncnse = np.convolve(nse, r) * dt\ncnse = cnse[:len(t)]\n\ns = 0.1 * np.sin(4 * np.pi * t) + cnse  # the signal"}]},{"title":"Create plots","body":["Now we will create the plots for our different spectrum representations. We will use Matplotlib's subplots function to create a 3x2 grid of plots. We will plot the time signal in the first plot and the different spectrum types in the remaining plots."],"code":[{"lang":"python","text":"fig, axs = plt.subplots(nrows=3, ncols=2, figsize=(7, 7))\n\n# plot time signal:\naxs[0, 0].set_title(\"Signal\")\naxs[0, 0].plot(t, s, color='C0')\naxs[0, 0].set_xlabel(\"Time\")\naxs[0, 0].set_ylabel(\"Amplitude\")\n\n# plot different spectrum types:\naxs[1, 0].set_title(\"Magnitude Spectrum\")\naxs[1, 0].magnitude_spectrum(s, Fs=Fs, color='C1')\n\naxs[1, 1].set_title(\"Log. Magnitude Spectrum\")\naxs[1, 1].magnitude_spectrum(s, Fs=Fs, scale='dB', color='C1')\n\naxs[2, 0].set_title(\"Phase Spectrum \")\naxs[2, 0].phase_spectrum(s, Fs=Fs, color='C2')\n\naxs[2, 1].set_title(\"Angle Spectrum\")\naxs[2, 1].angle_spectrum(s, Fs=Fs, color='C2')\n\naxs[0, 1].remove()  # don't display empty ax\n\nfig.tight_layout()\nplt.show()"}]},{"title":"Interpret plots","body":["We can see that the first plot shows the signal in the time domain. The second plot shows the magnitude spectrum of the signal, which tells us the strength of the different frequency components in the signal. The third plot shows the logarithmic magnitude spectrum, which is useful for visualizing the entire spectrum when there are very large and very small values. The fourth plot shows the phase spectrum, which tells us the phase shift of each frequency component in the signal. Finally, the fifth plot shows the angle spectrum, which is similar to the phase spectrum but uses radians instead of degrees."],"code":[]}],"commands":[],"reference":[],"source":"matplotlib/matplotlib · BSD 3-Clause"},"labex-matplotlib-matplotlib-spine-placement":{"intro":"In Matplotlib, the position of axis spines can be adjusted to customize the appearance of a plot. This lab will guide you through the process of adjusting spine positions in Matplotlib.","steps":[{"title":"Import necessary libraries","body":["In this step, we will import the necessary libraries for creating our plots."],"code":[{"lang":"python","text":"import matplotlib.pyplot as plt\nimport numpy as np"}]},{"title":"Create a basic plot","body":["In this step, we will create a basic plot to demonstrate the different spine placement options in Matplotlib."],"code":[{"lang":"python","text":"x = np.linspace(0, 2*np.pi, 100)\ny = 2 * np.sin(x)\n\nfig, ax_dict = plt.subplot_mosaic(\n    [['center', 'zero'],\n     ['axes', 'data']]\n)\nfig.suptitle('Spine positions')\n\nax = ax_dict['center']\nax.set_title(\"'center'\")\nax.plot(x, y)\nax.spines[['left', 'bottom']].set_position('center')\nax.spines[['top', 'right']].set_visible(False)\n\nax = ax_dict['zero']\nax.set_title(\"'zero'\")\nax.plot(x, y)\nax.spines[['left', 'bottom']].set_position('zero')\nax.spines[['top', 'right']].set_visible(False)\n\nax = ax_dict['axes']\nax.set_title(\"'axes' (0.2, 0.2)\")\nax.plot(x, y)\nax.spines.left.set_position(('axes', 0.2))\nax.spines.bottom.set_position(('axes', 0.2))\nax.spines[['top', 'right']].set_visible(False)\n\nax = ax_dict['data']\nax.set_title(\"'data' (1, 2)\")\nax.plot(x, y)\nax.spines.left.set_position(('data', 1))\nax.spines.bottom.set_position(('data', 2))\nax.spines[['top', 'right']].set_visible(False)"}]},{"title":"Define a method to adjust spine locations","body":["Define a method to adjust spine locations","In this step, we will define a method that adjusts the location of the axis spines based on the specified spine locations."],"code":[{"lang":"python","text":"def adjust_spines(ax, spines):\n    \"\"\"\n    Adjusts the location of the axis spines based on the specified spine locations.\n\n    Parameters:\n        ax (Axes): The Matplotlib Axes object to adjust the spines for.\n        spines (list of str): The desired spine locations. Valid options are 'left', 'right', 'top', 'bottom'.\n\n    Returns:\n        None\n    \"\"\"\n    for loc, spine in ax.spines.items():\n        if loc in spines:\n            spine.set_position(('outward', 10))  # move the spine outward by 10 points\n        else:\n            spine.set_color('none')  # don't draw the spine\n\n    # turn off ticks where there is no spine\n    if 'left' in spines:\n        ax.yaxis.set_ticks_position('left')\n    else:\n        ax.yaxis.set_ticks([])\n\n    if 'bottom' in spines:\n        ax.xaxis.set_ticks_position('bottom')\n    else:\n        ax.xaxis.set_ticks([])"}]},{"title":"Create a plot using the adjust_spines method","body":["Create a plot using the adjust_spines method","In this step, we will create a plot using the adjust_spines method to demonstrate how to adjust spine locations."],"code":[{"lang":"python","text":"fig = plt.figure()\n\nx = np.linspace(0, 2 * np.pi, 100)\ny = 2 * np.sin(x)\n\nax = fig.add_subplot(2, 2, 1)\nax.plot(x, y, clip_on=False)\nadjust_spines(ax, ['left'])\n\nax = fig.add_subplot(2, 2, 2)\nax.plot(x, y, clip_on=False)\nadjust_spines(ax, [])\n\nax = fig.add_subplot(2, 2, 3)\nax.plot(x, y, clip_on=False)\nadjust_spines(ax, ['left', 'bottom'])\n\nax = fig.add_subplot(2, 2, 4)\nax.plot(x, y, clip_on=False)\nadjust_spines(ax, ['bottom'])\n\nplt.show()"}]}],"commands":[],"reference":[{"path":"reference.py","text":"fig = plt.figure()\n\nx = np.linspace(0, 2 * np.pi, 100)\ny = 2 * np.sin(x)\n\nax = fig.add_subplot(2, 2, 1)\nax.plot(x, y, clip_on=False)\nadjust_spines(ax, ['left'])\n\nax = fig.add_subplot(2, 2, 2)\nax.plot(x, y, clip_on=False)\nadjust_spines(ax, [])\n\nax = fig.add_subplot(2, 2, 3)\nax.plot(x, y, clip_on=False)\nadjust_spines(ax, ['left', 'bottom'])\n\nax = fig.add_subplot(2, 2, 4)\nax.plot(x, y, clip_on=False)\nadjust_spines(ax, ['bottom'])\n\nplt.show()"}],"source":"matplotlib/matplotlib · BSD 3-Clause"},"labex-matplotlib-customize-matplotlib-spines":{"intro":"In this lab, you will learn how to customize spines in Matplotlib. Spines are the lines that connect the axis tick marks and demarcate the boundaries of the data area. By default, Matplotlib displays spines on all four sides of the plot. However, you may want to customize these spines to better highlight your data.","steps":[{"title":"Import Matplotlib and NumPy","body":["First, we need to import Matplotlib and NumPy libraries to create our plot. We will use NumPy to create sample data for our plot."],"code":[{"lang":"python","text":"import matplotlib.pyplot as plt\nimport numpy as np"}]},{"title":"Create Sample Data","body":["Next, we will create sample data for our plot using NumPy. We will generate 100 data points between 0 and 2π and compute their corresponding sine values."],"code":[{"lang":"python","text":"x = np.linspace(0, 2 * np.pi, 100)\ny = 2 * np.sin(x)"}]},{"title":"Create Subplots","body":["We will create three subplots to demonstrate different spine customizations. We will use constrained layout to ensure that the labels do not overlap the axes."],"code":[{"lang":"python","text":"fig, (ax0, ax1, ax2) = plt.subplots(nrows=3, layout='constrained')"}]},{"title":"Customize Spines for All Four Sides","body":["Customize Spines for All Four Sides","In the first subplot, we will display spines on all four sides of the plot. We can access the spines of each subplot using the container ax.spines. We can then customize the spines using various methods."],"code":[{"lang":"python","text":"ax0.plot(x, y)\nax0.set_title('Normal Spines')"}]},{"title":"Customize Spines for Bottom and Left Sides","body":["Customize Spines for Bottom and Left Sides","In the second subplot, we will display spines only on the bottom and left sides of the plot. We can hide the spines on the right and top sides of the plot using the set_visible method."],"code":[{"lang":"python","text":"ax1.plot(x, y)\nax1.set_title('Bottom-Left Spines')\n\n# Hide the right and top spines\nax1.spines.right.set_visible(False)\nax1.spines.top.set_visible(False)"}]},{"title":"Customize Spines with Bounds Limited to Data Range","body":["Customize Spines with Bounds Limited to Data Range","In the third subplot, we will display spines with bounds limited to the data range. We can limit the extent of each spine to the data range using the set_bounds method."],"code":[{"lang":"python","text":"ax2.plot(x, y)\nax2.set_title('Spines with Bounds Limited to Data Range')\n\n# Only draw spines for the data range, not in the margins\nax2.spines.bottom.set_bounds(x.min(), x.max())\nax2.spines.left.set_bounds(y.min(), y.max())\n# Hide the right and top spines\nax2.spines.right.set_visible(False)\nax2.spines.top.set_visible(False)"}]},{"title":"Show the Plot","body":["Finally, we will display the plot using the show method."],"code":[{"lang":"python","text":"plt.show()"}]}],"commands":[],"reference":[],"source":"matplotlib/matplotlib · BSD 3-Clause"},"labex-matplotlib-matplotlib-visualization-with-dropped-spines":{"intro":"In this lab, we will learn how to create a visualization using Matplotlib with 'dropped spines'. Dropped spines refers to the visualization technique where the spines of the axes (the lines around the plot) are moved to the outer edges of the plot area.","steps":[{"title":"Import Libraries","body":["First, we need to import the necessary libraries. We will be using the Matplotlib library and NumPy for generating random data."],"code":[{"lang":"python","text":"import matplotlib.pyplot as plt\nimport numpy as np"}]},{"title":"Set the Random Seed","body":["For reproducibility, we will set the random seed using NumPy."],"code":[{"lang":"python","text":"np.random.seed(19680801)"}]},{"title":"Create a Figure and Axes","body":["We will create a figure and an axes object using plt.subplots(). The imshow() function is used to display the random data as an image."],"code":[{"lang":"python","text":"fig, ax = plt.subplots()\n\nimage = np.random.uniform(size=(10, 10))\nax.imshow(image, cmap=plt.cm.gray)\nax.set_title('dropped spines')"}]},{"title":"Offset the Spines","body":["We will move the left and bottom spines outward by 10 points using the set_position() function. The argument for set_position() is a tuple with two elements. The first element represents the position of the spine, and the second element represents the distance from the spine to the plot area."],"code":[{"lang":"python","text":"ax.spines[['left', 'bottom']].set_position(('outward', 10))"}]},{"title":"Hide the Top and Right Spines","body":["We will hide the top and right spines using the set_visible() function."],"code":[{"lang":"python","text":"ax.spines[['top', 'right']].set_visible(False)"}]},{"title":"Display the Plot","body":["Finally, we will display the plot using plt.show()."],"code":[{"lang":"python","text":"plt.show()"}]}],"commands":[],"reference":[],"source":"matplotlib/matplotlib · BSD 3-Clause"},"labex-matplotlib-plotting-sparsity-patterns":{"intro":"In this tutorial, we will learn how to plot sparsity patterns of arrays using Matplotlib. The sparsity pattern refers to the distribution of non-zero elements in an array. We will use the spy function in Matplotlib to plot the sparsity patterns.","steps":[{"title":"Importing Required Libraries","body":["We will start by importing the required libraries which are NumPy and Matplotlib."],"code":[{"lang":"python","text":"import matplotlib.pyplot as plt\nimport numpy as np"}]},{"title":"Creating Random Array","body":["Next, we will create a random array with dimensions (20, 20) using the numpy.random.randn function. We will also set a few elements to zero to create a sparse matrix."],"code":[{"lang":"python","text":"np.random.seed(19680801)\nx = np.random.randn(20, 20)\nx[5, :] = 0.\nx[:, 12] = 0."}]},{"title":"Creating Subplots","body":["We will now create a 2x2 grid of subplots using the subplots function. This will give us four plots to visualize the sparsity pattern of the array."],"code":[{"lang":"python","text":"fig, axs = plt.subplots(2, 2)\nax1 = axs[0, 0]\nax2 = axs[0, 1]\nax3 = axs[1, 0]\nax4 = axs[1, 1]"}]},{"title":"Plotting Sparsity Pattern","body":["We will use the spy function to plot the sparsity pattern of the array. We will use different parameters such as markersize and precision to customize the plot."],"code":[{"lang":"python","text":"ax1.spy(x, markersize=5)\nax2.spy(x, precision=0.1, markersize=5)\nax3.spy(x)\nax4.spy(x, precision=0.1)"}]},{"title":"Displaying the Plots","body":["Finally, we will display the plots using the show function."],"code":[{"lang":"python","text":"plt.show()"}]}],"commands":[],"reference":[],"source":"matplotlib/matplotlib · BSD 3-Clause"},"labex-matplotlib-matplotlib-stackplots-and-streamgraphs":{"intro":"In this lab, you will learn how to use Matplotlib to create stackplots and streamgraphs. Stackplots are useful when you want to visualize multiple datasets as vertically stacked areas. Streamgraphs are a variation of stackplots where the baseline of the plot is not fixed at zero. Instead, the baseline is 'wiggled' so that the areas of the plot are smoothed and flow into each other.","steps":[{"title":"Import Libraries","body":["The first step is to import the necessary libraries, which in this case are Matplotlib and NumPy."],"code":[{"lang":"python","text":"import matplotlib.pyplot as plt\nimport numpy as np"}]},{"title":"Create Stackplot","body":["The second step is to create a stackplot using the stackplot() function. We will use data from the United Nations World Population Prospects (Revision 2019) to create a stackplot of the world population by continent from 1950 to 2018."],"code":[{"lang":"python","text":"# data from United Nations World Population Prospects (Revision 2019)\n# https://population.un.org/wpp/, license: CC BY 3.0 IGO\nyear = [1950, 1960, 1970, 1980, 1990, 2000, 2010, 2018]\npopulation_by_continent = {\n    'africa': [228, 284, 365, 477, 631, 814, 1044, 1275],\n    'americas': [340, 425, 519, 619, 727, 840, 943, 1006],\n    'asia': [1394, 1686, 2120, 2625, 3202, 3714, 4169, 4560],\n    'europe': [220, 253, 276, 295, 310, 303, 294, 293],\n    'oceania': [12, 15, 19, 22, 26, 31, 36, 39],\n}\n\nfig, ax = plt.subplots()\nax.stackplot(year, population_by_continent.values(),\n             labels=population_by_continent.keys(), alpha=0.8)\nax.legend(loc='upper left', reverse=True)\nax.set_title('World population')\nax.set_xlabel('Year')\nax.set_ylabel('Number of people (millions)')\n\nplt.show()"}]},{"title":"Create Streamgraph","body":["The third step is to create a streamgraph using the stackplot() function with the baseline parameter set to 'wiggle'. We will create a random mixture of Gaussians and plot them as a streamgraph."],"code":[{"lang":"python","text":"# Fixing random state for reproducibility\nnp.random.seed(19680801)\n\n\ndef gaussian_mixture(x, n=5):\n    \"\"\"Return a random mixture of *n* Gaussians, evaluated at positions *x*.\"\"\"\n    def add_random_gaussian(a):\n        amplitude = 1 / (.1 + np.random.random())\n        dx = x[-1] - x[0]\n        x0 = (2 * np.random.random() - .5) * dx\n        z = 10 / (.1 + np.random.random()) / dx\n        a += amplitude * np.exp(-(z * (x - x0))**2)\n    a = np.zeros_like(x)\n    for j in range(n):\n        add_random_gaussian(a)\n    return a\n\n\nx = np.linspace(0, 100, 101)\nys = [gaussian_mixture(x) for _ in range(3)]\n\nfig, ax = plt.subplots()\nax.stackplot(x, ys, baseline='wiggle')\nplt.show()"}]}],"commands":[],"reference":[{"path":"reference.py","text":"# Fixing random state for reproducibility\nnp.random.seed(19680801)\n\n\ndef gaussian_mixture(x, n=5):\n    \"\"\"Return a random mixture of *n* Gaussians, evaluated at positions *x*.\"\"\"\n    def add_random_gaussian(a):\n        amplitude = 1 / (.1 + np.random.random())\n        dx = x[-1] - x[0]\n        x0 = (2 * np.random.random() - .5) * dx\n        z = 10 / (.1 + np.random.random()) / dx\n        a += amplitude * np.exp(-(z * (x - x0))**2)\n    a = np.zeros_like(x)\n    for j in range(n):\n        add_random_gaussian(a)\n    return a\n\n\nx = np.linspace(0, 100, 101)\nys = [gaussian_mixture(x) for _ in range(3)]\n\nfig, ax = plt.subplots()\nax.stackplot(x, ys, baseline='wiggle')\nplt.show()"}],"source":"matplotlib/matplotlib · BSD 3-Clause"},"labex-matplotlib-matplotlib-stepwise-histogram-tutorial":{"intro":"Matplotlib is a data visualization library in Python. It is widely used for creating a wide range of visualizations like line plots, scatter plots, bar plots, histograms, and more. This tutorial will focus on creating stepwise histograms using Matplotlib.","steps":[{"title":"Import the necessary libraries and modules","body":["Import the necessary libraries and modules"],"code":[{"lang":"python","text":"import matplotlib.pyplot as plt\nimport numpy as np\n\nfrom matplotlib.patches import StepPatch"}]},{"title":"Prepare the data","body":[],"code":[{"lang":"python","text":"np.random.seed(0)\nh, edges = np.histogram(np.random.normal(5, 3, 5000),\n                        bins=np.linspace(0, 10, 20))"}]},{"title":"Create a simple step histogram","body":["Create a simple step histogram"],"code":[{"lang":"python","text":"plt.stairs(h, edges, label='Simple histogram')\nplt.legend()\nplt.show()"}]},{"title":"Modify the baseline of the step histogram","body":["Modify the baseline of the step histogram"],"code":[{"lang":"python","text":"plt.stairs(h, edges + 5, baseline=50, label='Modified baseline')\nplt.legend()\nplt.show()"}]},{"title":"Create a step histogram without edges","body":["Create a step histogram without edges"],"code":[{"lang":"python","text":"plt.stairs(h, edges + 10, baseline=None, label='No edges')\nplt.legend()\nplt.show()"}]},{"title":"Create a filled histogram","body":[],"code":[{"lang":"python","text":"plt.stairs(np.arange(1, 6, 1), fill=True,\n              label='Filled histogram\\nw/ automatic edges')\nplt.legend()\nplt.show()"}]},{"title":"Create a hatched histogram","body":[],"code":[{"lang":"python","text":"plt.stairs(np.arange(1, 6, 1)*0.3, np.arange(2, 8, 1),\n              orientation='horizontal', hatch='//',\n              label='Hatched histogram\\nw/ horizontal orientation')\nplt.legend()\nplt.show()"}]},{"title":"Create a StepPatch artist","body":[],"code":[{"lang":"python","text":"patch = StepPatch(values=[1, 2, 3, 2, 1],\n                  edges=range(1, 7),\n                  label=('Patch derived underlying object\\n'\n                         'with default edge/facecolor behaviour'))\nplt.gca().add_patch(patch)\nplt.xlim(0, 7)\nplt.ylim(-1, 5)\nplt.legend()\nplt.show()"}]}],"commands":[],"reference":[{"path":"reference.py","text":"bins = np.arange(14)\ncenters = bins[:-1] + np.diff(bins) / 2\ny = np.sin(centers / 2)\n\nplt.step(bins[:-1], y, where='post', label='step(where=\"post\")')\nplt.plot(bins[:-1], y, 'o--', color='grey', alpha=0.3)\n\nplt.stairs(y - 1, bins, baseline=None, label='stairs()')\nplt.plot(centers, y - 1, 'o--', color='grey', alpha=0.3)\nplt.plot(np.repeat(bins, 2), np.hstack([y[0], np.repeat(y, 2), y[-1]]) - 1,\n         'o', color='red', alpha=0.2)\n\nplt.legend()\nplt.title('step() vs. stairs()')\nplt.show()"}],"source":"matplotlib/matplotlib · BSD 3-Clause"},"labex-matplotlib-stem-plot-visualization-with-python":{"intro":"The stem plot is a type of plot used in data visualization. It is used to plot vertical lines from a baseline to the y-coordinate and places a marker at the tip. In this lab, we will learn how to use the stem plot function in Python's Matplotlib library.","steps":[{"title":"Import Libraries","body":["Before we begin, we need to import the necessary libraries. In this case, we will be using the Matplotlib and Numpy libraries."],"code":[{"lang":"python","text":"import matplotlib.pyplot as plt\nimport numpy as np"}]},{"title":"Generate Data","body":["Next, we need to generate some data to use in our stem plot. We will create two arrays using the Numpy library."],"code":[{"lang":"python","text":"x = np.linspace(0.1, 2 * np.pi, 41)\ny = np.exp(np.sin(x))"}]},{"title":"Create a Basic Stem Plot","body":["We can now create a basic stem plot using the stem function from the Matplotlib library.","This will generate a plot with vertical lines from the baseline to the y-coordinate and markers at the tip."],"code":[{"lang":"python","text":"plt.stem(x, y)\nplt.show()"}]},{"title":"Customizing the Plot","body":["We can customize the plot by adjusting the baseline using the bottom parameter. We can also adjust the format properties of the plot using the linefmt, markerfmt, and basefmt parameters.","This will generate a plot with a grey line format and diamond-shaped markers. The baseline has also been adjusted to 1.1."],"code":[{"lang":"python","text":"markerline, stemlines, baseline = plt.stem(\n    x, y, linefmt='grey', markerfmt='D', bottom=1.1)\nmarkerline.set_markerfacecolor('none')\nplt.show()"}]}],"commands":[],"reference":[{"path":"reference.py","text":"markerline, stemlines, baseline = plt.stem(\n    x, y, linefmt='grey', markerfmt='D', bottom=1.1)\nmarkerline.set_markerfacecolor('none')\nplt.show()"}],"source":"matplotlib/matplotlib · BSD 3-Clause"},"labex-matplotlib-3d-stem-plot":{"intro":"This lab demonstrates how to create a 3D stem plot using the Matplotlib library in Python. A stem plot is a way of plotting data points by drawing vertical lines from a baseline to the data point and placing a marker at the tip.","steps":[{"title":"Import the necessary libraries","body":["Import the necessary libraries","In this step, we will import the Matplotlib and Numpy libraries using the import statement."],"code":[{"lang":"python","text":"import matplotlib.pyplot as plt\nimport numpy as np"}]},{"title":"Define the data","body":["In this step, we will define the data that we will use to create the 3D stem plot. We will create a linspace array for the angle, and use sine and cosine functions to calculate the x and y coordinates. We will also define the z coordinate as the angle."],"code":[{"lang":"python","text":"theta = np.linspace(0, 2*np.pi)\nx = np.cos(theta - np.pi/2)\ny = np.sin(theta - np.pi/2)\nz = theta"}]},{"title":"Create the 3D stem plot","body":["In this step, we will create the 3D stem plot using the stem function from Matplotlib. We will pass the x, y, and z coordinates as arguments to the stem function."],"code":[{"lang":"python","text":"fig, ax = plt.subplots(subplot_kw=dict(projection='3d'))\nax.stem(x, y, z)\n\nplt.show()"}]},{"title":"Customize the plot","body":["In this step, we will customize the 3D stem plot by changing the baseline using the bottom parameter and changing the format using the linefmt, markerfmt, and basefmt parameters."],"code":[{"lang":"python","text":"fig, ax = plt.subplots(subplot_kw=dict(projection='3d'))\nmarkerline, stemlines, baseline = ax.stem(\n    x, y, z, linefmt='grey', markerfmt='D', bottom=np.pi)\nmarkerline.set_markerfacecolor('none')\n\nplt.show()"}]},{"title":"Change the orientation of the plot","body":["Change the orientation of the plot","In this step, we will change the orientation of the plot using the orientation parameter. We will set the orientation to 'x' so that the stems are projected along the x-direction and the baseline is in the yz-plane."],"code":[{"lang":"python","text":"fig, ax = plt.subplots(subplot_kw=dict(projection='3d'))\nmarkerline, stemlines, baseline = ax.stem(x, y, z, bottom=-1, orientation='x')\nax.set(xlabel='x', ylabel='y', zlabel='z')\n\nplt.show()"}]}],"commands":[],"reference":[{"path":"reference.py","text":"fig, ax = plt.subplots(subplot_kw=dict(projection='3d'))\nmarkerline, stemlines, baseline = ax.stem(x, y, z, bottom=-1, orientation='x')\nax.set(xlabel='x', ylabel='y', zlabel='z')\n\nplt.show()"}],"source":"matplotlib/matplotlib · BSD 3-Clause"},"labex-matplotlib-using-matplotlib-s-step-and-plot-functions":{"intro":"Matplotlib is a plotting library for the Python programming language and its numerical mathematics extension NumPy. It provides an object-oriented API for embedding plots into applications using general-purpose GUI toolkits like Tkinter, wxPython, Qt, or GTK. Matplotlib was originally developed by John D. Hunter in 2003.","steps":[{"title":"Import necessary libraries","body":["First, we need to import the necessary libraries, which are matplotlib.pyplot and numpy."],"code":[{"lang":"python","text":"import matplotlib.pyplot as plt\nimport numpy as np"}]},{"title":"Create data for the plot","body":["Next, let's create some data that we will use to plot. We will use the numpy.arange() function to create an array of values from 0 to 14 and store it in the variable x. We will also use the numpy.sin() function to create an array of values that are the sine of each value in x divided by 2, and store it in the variable y."],"code":[{"lang":"python","text":"x = np.arange(14)\ny = np.sin(x / 2)"}]},{"title":"Plot using .step()","body":["We can use the .step() function to create piece-wise constant curves. The where parameter determines where the steps should be drawn. We will create three plots using different values for where.","The above code will create a plot with three piece-wise constant curves, each with a different value for where."],"code":[{"lang":"python","text":"plt.step(x, y + 2, label='pre (default)', where='pre')\nplt.step(x, y + 1, label='mid', where='mid')\nplt.step(x, y, label='post', where='post')\nplt.legend()\nplt.show()"}]},{"title":"Plot using .plot()","body":["We can achieve the same behavior as .step() by using the drawstyle parameter of the .plot() function. We will create three plots using different values for drawstyle.","The above code will create a plot with three piece-wise constant curves, each with a different value for drawstyle."],"code":[{"lang":"python","text":"plt.plot(x, y + 2, drawstyle='steps', label='steps (=steps-pre)')\nplt.plot(x, y + 1, drawstyle='steps-mid', label='steps-mid')\nplt.plot(x, y, drawstyle='steps-post', label='steps-post')\nplt.legend()\nplt.show()"}]}],"commands":[],"reference":[{"path":"reference.py","text":"plt.plot(x, y + 2, drawstyle='steps', label='steps (=steps-pre)')\nplt.plot(x, y + 1, drawstyle='steps-mid', label='steps-mid')\nplt.plot(x, y, drawstyle='steps-post', label='steps-post')\nplt.legend()\nplt.show()"}],"source":"matplotlib/matplotlib · BSD 3-Clause"},"labex-matplotlib-stix-fonts-demo":{"intro":"This is a step-by-step tutorial on how to use Matplotlib to plot mathematical equations and text using different fonts.","steps":[{"title":"Install Matplotlib","body":[],"code":[{"lang":"text","text":"pip install matplotlib"}]},{"title":"Import Matplotlib and Define Text","body":["Import Matplotlib and Define Text","In this step, we import Matplotlib and define the text that we will be plotting using different fonts."],"code":[{"lang":"python","text":"import matplotlib.pyplot as plt\n\ncircle123 = \"\\N{CIRCLED DIGIT ONE}\\N{CIRCLED DIGIT TWO}\\N{CIRCLED DIGIT THREE}\"\n\ntests = [\n    r'$%s\\;\\mathrm{%s}\\;\\mathbf{%s}$' % ((circle123,) * 3),\n    r'$\\mathsf{Sans \\Omega}\\;\\mathrm{\\mathsf{Sans \\Omega}}\\;'\n    r'\\mathbf{\\mathsf{Sans \\Omega}}$',\n    r'$\\mathtt{Monospace}$',\n    r'$\\mathcal{CALLIGRAPHIC}$',\n    r'$\\mathbb{Blackboard\\;\\pi}$',\n    r'$\\mathrm{\\mathbb{Blackboard\\;\\pi}}$',\n    r'$\\mathbf{\\mathbb{Blackboard\\;\\pi}}$',\n    r'$\\mathfrak{Fraktur}\\;\\mathbf{\\mathfrak{Fraktur}}$',\n    r'$\\mathscr{Script}$',\n]"}]},{"title":"Plot the Text","body":["Now that we have defined the text, we can plot it using Matplotlib. In this step, we create a figure and add the text to it using the fig.text() method."],"code":[{"lang":"python","text":"fig = plt.figure(figsize=(8, len(tests) + 2))\nfor i, s in enumerate(tests[::-1]):\n    fig.text(0, (i + .5) / len(tests), s, fontsize=32)\n\nplt.show()"}]},{"title":"Analyze the Output","body":["After running the code, we should see the plotted text using different fonts. The output should look like this:","![plotted text with fonts](https://i.imgur.com/LQ79zHJ.png)"],"code":[]}],"commands":["pip install matplotlib"],"reference":[],"source":"matplotlib/matplotlib · BSD 3-Clause"},"labex-matplotlib-create-customized-stock-price-graphs":{"intro":"In this lab, you will learn how to create a graph of multiple time series that demonstrates custom styling of plot frame, tick lines, tick labels, and line graph properties using Matplotlib. The graph will display stock prices of various companies over a period of 32 years.","steps":[{"title":"Import necessary libraries","body":[],"code":[{"lang":"python","text":"import matplotlib.pyplot as plt\nimport numpy as np\nfrom matplotlib.cbook import get_sample_data\nimport matplotlib.transforms as mtransforms"}]},{"title":"Load the stock data","body":[],"code":[{"lang":"python","text":"with get_sample_data('Stocks.csv') as file:\n    stock_data = np.genfromtxt(\n        file, delimiter=',', names=True, dtype=None,\n        converters={0: lambda x: np.datetime64(x, 'D')}, skip_header=1)"}]},{"title":"Create a figure and axis object","body":["Create a figure and axis object"],"code":[{"lang":"python","text":"fig, ax = plt.subplots(1, 1, figsize=(6, 8), layout='constrained')"}]},{"title":"Define the colors to be used in the plot","body":["Define the colors to be used in the plot"],"code":[{"lang":"python","text":"ax.set_prop_cycle(color=[\n    '#1f77b4', '#aec7e8', '#ff7f0e', '#ffbb78', '#2ca02c', '#98df8a',\n    '#d62728', '#ff9896', '#9467bd', '#c5b0d5', '#8c564b', '#c49c94',\n    '#e377c2', '#f7b6d2', '#7f7f7f', '#c7c7c7', '#bcbd22', '#dbdb8d',\n    '#17becf', '#9edae5'])"}]},{"title":"Set the names and tickers of the stocks to be plotted","body":["Set the names and tickers of the stocks to be plotted"],"code":[{"lang":"python","text":"stocks_name = ['IBM', 'Apple', 'Microsoft', 'Xerox', 'Amazon', 'Dell',\n               'Alphabet', 'Adobe', 'S&P 500', 'NASDAQ']\nstocks_ticker = ['IBM', 'AAPL', 'MSFT', 'XRX', 'AMZN', 'DELL', 'GOOGL',\n                 'ADBE', 'GSPC', 'IXIC']"}]},{"title":"Manually adjust the label positions vertically to avoid overlapping","body":["Manually adjust the label positions vertically to avoid overlapping"],"code":[{"lang":"python","text":"y_offsets = {k: 0 for k in stocks_ticker}\ny_offsets['IBM'] = 5\ny_offsets['AAPL'] = -5\ny_offsets['AMZN'] = -6"}]},{"title":"Plot each stock separately with its own color","body":["Plot each stock separately with its own color"],"code":[{"lang":"python","text":"for nn, column in enumerate(stocks_ticker):\n    # Plot each line separately with its own color.\n    # don't include any data with NaN.\n    good = np.nonzero(np.isfinite(stock_data[column]))\n    line, = ax.plot(stock_data['Date'][good], stock_data[column][good], lw=2.5)\n\n    # Add a text label to the right end of every line. Most of the code below\n    # is adding specific offsets y position because some labels overlapped.\n    y_pos = stock_data[column][-1]\n\n    # Use an offset transform, in points, for any text that needs to be nudged\n    # up or down.\n    offset = y_offsets[column] / 72\n    trans = mtransforms.ScaledTranslation(0, offset, fig.dpi_scale_trans)\n    trans = ax.transData + trans\n\n    # Again, make sure that all labels are large enough to be easily read\n    # by the viewer.\n    ax.text(np.datetime64('2022-10-01'), y_pos, stocks_name[nn],\n            color=line.get_color(), transform=trans)"}]},{"title":"Set the limits of the x-axis and y-axis, and add title and grid","body":["Set the limits of the x-axis and y-axis, and add title and grid"],"code":[{"lang":"python","text":"ax.set_xlim(np.datetime64('1989-06-01'), np.datetime64('2023-01-01'))\nfig.suptitle(\"Technology company stocks prices dollars (1990-2022)\", ha=\"center\")\nax.spines[:].set_visible(False)\nax.xaxis.tick_bottom()\nax.yaxis.tick_left()\nax.set_yscale('log')\nax.grid(True, 'major', 'both', ls='--', lw=.5, c='k', alpha=.3)\nax.tick_params(axis='both', which='both', labelsize='large',\n               bottom=False, top=False, labelbottom=True,\n               left=False, right=False, labelleft=True)"}]}],"commands":[],"reference":[],"source":"matplotlib/matplotlib · BSD 3-Clause"},"labex-matplotlib-create-real-time-oscilloscope-with-matplotli":{"intro":"This tutorial is a step-by-step guide on how to create an oscilloscope using Python's Matplotlib library. An oscilloscope is a device used to measure and display voltage signals over time. In this tutorial, we will use Matplotlib's animation module to create a real-time display of a voltage signal.","steps":[{"title":"Import Libraries","body":["Before we start coding, we need to import the necessary libraries. We will be using Matplotlib, NumPy, and the animation module."],"code":[{"lang":"python","text":"import matplotlib.pyplot as plt\nimport numpy as np\nimport matplotlib.animation as animation\nfrom matplotlib.lines import Line2D"}]},{"title":"Set up the Scope Class","body":["The Scope class will hold the data and methods we need to create the oscilloscope. In the constructor, we initialize the necessary variables and set up the plot."],"code":[{"lang":"python","text":"class Scope:\n    def __init__(self, ax, maxt=2, dt=0.02):\n        self.ax = ax\n        self.dt = dt\n        self.maxt = maxt\n        self.tdata = [0]\n        self.ydata = [0]\n        self.line = Line2D(self.tdata, self.ydata)\n        self.ax.add_line(self.line)\n        self.ax.set_ylim(-.1, 1.1)\n        self.ax.set_xlim(0, self.maxt)"}]},{"title":"Define the Update Method","body":["The update method is called for each frame of the animation. It takes in a new value and updates the plot accordingly."],"code":[{"lang":"python","text":"def update(self, y):\n        lastt = self.tdata[-1]\n        if lastt >= self.tdata[0] + self.maxt:  # reset the arrays\n            self.tdata = [self.tdata[-1]]\n            self.ydata = [self.ydata[-1]]\n            self.ax.set_xlim(self.tdata[0], self.tdata[0] + self.maxt)\n            self.ax.figure.canvas.draw()\n\n        t = self.tdata[0] + len(self.tdata) * self.dt\n\n        self.tdata.append(t)\n        self.ydata.append(y)\n        self.line.set_data(self.tdata, self.ydata)\n        return self.line,"}]},{"title":"Create the Emitter Function","body":["The emitter function generates the data that will be passed to the update method. In this case, we are generating random data with a probability of 0.1."],"code":[{"lang":"python","text":"def emitter(p=0.1):\n    while True:\n        v = np.random.rand()\n        if v > p:\n            yield 0.\n        else:\n            yield np.random.rand()"}]},{"title":"Set up the Plot","body":["We create a new figure and axis object and initialize the Scope class. We then pass the update and emitter functions to the FuncAnimation method to create the animation."],"code":[{"lang":"python","text":"fig, ax = plt.subplots()\nscope = Scope(ax)\n\nani = animation.FuncAnimation(fig, scope.update, emitter, interval=50,\n                              blit=True, save_count=100)\n\nplt.show()"}]}],"commands":[],"reference":[{"path":"reference.py","text":"fig, ax = plt.subplots()\nscope = Scope(ax)\n\nani = animation.FuncAnimation(fig, scope.update, emitter, interval=50,\n                              blit=True, save_count=100)\n\nplt.show()"}],"source":"matplotlib/matplotlib · BSD 3-Clause"},"labex-matplotlib-matplotlib-style-sheets":{"intro":"Matplotlib is a powerful data visualization library in Python. It allows you to create a variety of plots, such as scatter plots, histograms, bar graphs, and more. The style sheets reference script demonstrates the different available style sheets on a common set of example plots. In this lab, you will learn how to use Matplotlib style sheets to customize the appearance of your plots.","steps":[{"title":"Import libraries","body":["Before you get started, you need to import the necessary libraries. In this lab, you will be using Matplotlib and NumPy."],"code":[{"lang":"python","text":"import matplotlib.pyplot as plt\nimport numpy as np"}]},{"title":"Define the plot functions","body":["Next, you need to define the plot functions that will be used to create the example plots. In this step, you will define the following plot functions:","• plot_scatter(): creates a scatter plot • plot_colored_lines(): plots lines with colors following the style color cycle • plot_bar_graphs(): creates a bar graph • plot_colored_circles(): plots circle patches • plot_image_and_patch(): plots an image with a circular patch • plot_histograms(): creates histograms"],"code":[{"lang":"python","text":"def plot_scatter(ax, prng, nb_samples=100):\n    \"\"\"Scatter plot.\"\"\"\n    for mu, sigma, marker in [(-.5, 0.75, 'o'), (0.75, 1., 's')]:\n        x, y = prng.normal(loc=mu, scale=sigma, size=(2, nb_samples))\n        ax.plot(x, y, ls='none', marker=marker)\n    ax.set_xlabel('X-label')\n    ax.set_title('Axes title')\n    return ax\n\n\ndef plot_colored_lines(ax):\n    \"\"\"Plot lines with colors following the style color cycle.\"\"\"\n    t = np.linspace(-10, 10, 100)\n\n    def sigmoid(t, t0):\n        return 1 / (1 + np.exp(-(t - t0)))\n\n    nb_colors = len(plt.rcParams['axes.prop_cycle'])\n    shifts = np.linspace(-5, 5, nb_colors)\n    amplitudes = np.linspace(1, 1.5, nb_colors)\n    for t0, a in zip(shifts, amplitudes):\n        ax.plot(t, a * sigmoid(t, t0), '-')\n    ax.set_xlim(-10, 10)\n    return ax\n\n\ndef plot_bar_graphs(ax, prng, min_value=5, max_value=25, nb_samples=5):\n    \"\"\"Plot two bar graphs side by side, with letters as x-tick labels.\"\"\"\n    x = np.arange(nb_samples)\n    ya, yb = prng.randint(min_value, max_value, size=(2, nb_samples))\n    width = 0.25\n    ax.bar(x, ya, width)\n    ax.bar(x + width, yb, width, color='C2')\n    ax.set_xticks(x + width, labels=['a', 'b', 'c', 'd', 'e'])\n    return ax\n\n\ndef plot_colored_circles(ax, prng, nb_samples=15):\n    \"\"\"\n    Plot circle patches.\n\n    NB: draws a fixed amount of samples, rather than using the length of\n    the color cycle, because different styles may have different numbers\n    of colors.\n    \"\"\"\n    for sty_dict, j in zip(plt.rcParams['axes.prop_cycle'](),\n                           range(nb_samples)):\n        ax.add_patch(plt.Circle(prng.normal(scale=3, size=2),"}]},{"title":"Define the plot function","body":["Now, you need to define the plot_figure() function that will set up and plot the demonstration figure with a given style. This function will call each of the plot functions defined in Step 2."],"code":[{"lang":"python","text":"def plot_figure(style_label=\"\"):\n    \"\"\"Setup and plot the demonstration figure with a given style.\"\"\"\n    # Use a dedicated RandomState instance to draw the same \"random\" values\n    # across the different figures.\n    prng = np.random.RandomState(96917002)\n\n    fig, axs = plt.subplots(ncols=6, nrows=1, num=style_label,\n                            figsize=(14.8, 2.8), layout='constrained')\n\n    # make a suptitle, in the same style for all subfigures,\n    # except those with dark backgrounds, which get a lighter color:\n    background_color = mcolors.rgb_to_hsv(\n        mcolors.to_rgb(plt.rcParams['figure.facecolor']))[2]\n    if background_color < 0.5:\n        title_color = [0.8, 0.8, 1]\n    else:\n        title_color = np.array([19, 6, 84]) / 256\n    fig.suptitle(style_label, x=0.01, ha='left', color=title_color,\n                 fontsize=14, fontfamily='DejaVu Sans', fontweight='normal')\n\n    plot_scatter(axs[0], prng)\n    plot_image_and_patch(axs[1], prng)\n    plot_bar_graphs(axs[2], prng)\n    plot_colored_lines(axs[3])\n    plot_histograms(axs[4], prng)\n    plot_colored_circles(axs[5], prng)\n\n    # add divider\n    rec = Rectangle((1 + 0.025, -2), 0.05, 16,\n                    clip_on=False, color='gray')\n\n    axs[4].add_artist(rec)"}]},{"title":"Plot the demonstration figure for each style sheet","body":["Plot the demonstration figure for each style sheet","Finally, you need to plot the demonstration figure for each available style sheet. You can do this by looping through the style_list and calling the plot_figure() function for each style sheet."],"code":[{"lang":"python","text":"if __name__ == \"__main__\":\n\n    # Set up a list of all available styles, in alphabetical order but\n    # the `default` and `classic` ones, which will be forced resp. in\n    # first and second position.\n    # styles with leading underscores are for internal use such as testing\n    # and plot types gallery. These are excluded here.\n    style_list = ['default', 'classic'] + sorted(\n        style for style in plt.style.available\n        if style != 'classic' and not style.startswith('_'))\n\n    # Plot a demonstration figure for every available style sheet.\n    for style_label in style_list:\n        with plt.rc_context({\"figure.max_open_warning\": len(style_list)}):\n            with plt.style.context(style_label):\n                plot_figure(style_label=style_label)\n\n    plt.show()"}]}],"commands":[],"reference":[{"path":"reference.py","text":"if __name__ == \"__main__\":\n\n    # Set up a list of all available styles, in alphabetical order but\n    # the `default` and `classic` ones, which will be forced resp. in\n    # first and second position.\n    # styles with leading underscores are for internal use such as testing\n    # and plot types gallery. These are excluded here.\n    style_list = ['default', 'classic'] + sorted(\n        style for style in plt.style.available\n        if style != 'classic' and not style.startswith('_'))\n\n    # Plot a demonstration figure for every available style sheet.\n    for style_label in style_list:\n        with plt.rc_context({\"figure.max_open_warning\": len(style_list)}):\n            with plt.style.context(style_label):\n                plot_figure(style_label=style_label)\n\n    plt.show()"}],"source":"matplotlib/matplotlib · BSD 3-Clause"},"labex-matplotlib-creating-matplotlib-subfigures":{"intro":"Matplotlib is a Python library used for creating visualizations, such as graphs, charts, and figures. In this lab, you will learn how to create subfigures in Matplotlib. Subfigures are figures that contain two or more plots within the same figure. Subfigures can help you to compare different data sets or to show different views of the same data. They are useful when you want to display multiple plots together.","steps":[{"title":"Import Libraries","body":["To use Matplotlib, you need to import it. You will also need to import NumPy to create arrays for the plots."],"code":[{"lang":"python","text":"import matplotlib.pyplot as plt\nimport numpy as np"}]},{"title":"Create a Figure with Subfigures","body":["Create a Figure with Subfigures","To create a figure with subfigures, you first need to create a figure object using plt.figure(). Then, you can create subfigures using fig.subfigures().","This will create a figure with two subfigures, one above the other."],"code":[{"lang":"python","text":"fig = plt.figure()\nsubfigs = fig.subfigures(2, 1)"}]},{"title":"Plot Data on Subfigures","body":["To plot data on the subfigures, you need to create a subplot for each subfigure using subfig.subplots(). Then, you can use any of the plotting functions in Matplotlib to create the plots.","This will create two subfigures, each with a plot of random data."],"code":[{"lang":"python","text":"ax1 = subfigs[0].subplots()\nax1.plot(np.arange(10), np.random.randn(10))\n\nax2 = subfigs[1].subplots()\nax2.plot(np.arange(10), np.random.randn(10))"}]},{"title":"Customize Subfigures","body":["You can customize the subfigures using the various functions available in Matplotlib. For example, you can set the title and axis labels using set_title() and set_xlabel()/set_ylabel().","This will set the titles and axis labels for each subfigure."],"code":[{"lang":"python","text":"ax1.set_title('Subfigure 1')\nax1.set_xlabel('X Label')\nax1.set_ylabel('Y Label')\n\nax2.set_title('Subfigure 2')\nax2.set_xlabel('X Label')\nax2.set_ylabel('Y Label')"}]},{"title":"Display the Figure","body":["To display the figure, you need to use plt.show().","This will display the figure with the two subfigures."],"code":[{"lang":"python","text":"plt.show()"}]}],"commands":[],"reference":[],"source":"matplotlib/matplotlib · BSD 3-Clause"},"labex-matplotlib-matplotlib-subplot-creation-tutorial":{"intro":"In data visualization, it is often necessary to plot multiple graphs in a single figure. Matplotlib allows us to achieve this using subplots. In this lab, we will learn how to create subplots in Matplotlib.","steps":[{"title":"Import Libraries","body":["First, we need to import the required libraries. We will be using Matplotlib and NumPy. NumPy is used to generate some sample data."],"code":[{"lang":"python","text":"import matplotlib.pyplot as plt\nimport numpy as np"}]},{"title":"Generate Some Sample Data","body":["We will generate some sample data that we will use to plot our graphs."],"code":[{"lang":"python","text":"# Create some fake data.\nx1 = np.linspace(0.0, 5.0)\ny1 = np.cos(2 * np.pi * x1) * np.exp(-x1)\nx2 = np.linspace(0.0, 2.0)\ny2 = np.cos(2 * np.pi * x2)"}]},{"title":"Create Subplots Using subplots()","body":["Create Subplots Using subplots()","We will create subplots using subplots() function. We will create two subplots, one above the other."],"code":[{"lang":"python","text":"# Create subplots\nfig, (ax1, ax2) = plt.subplots(2, 1)"}]},{"title":"Set Title and Axes Labels","body":["We will set the title and axis labels for our subplots."],"code":[{"lang":"python","text":"# Set title and axis labels\nfig.suptitle('A tale of 2 subplots')\n\nax1.set_ylabel('Damped oscillation')\nax2.set_xlabel('time (s)')\nax2.set_ylabel('Undamped')"}]},{"title":"Plot Data on Subplots","body":["We will now plot our data on the subplots."],"code":[{"lang":"python","text":"# Plot data on subplots\nax1.plot(x1, y1, 'o-')\nax2.plot(x2, y2, '.-')"}]},{"title":"Display the Plots","body":["Finally, we will display the plots using plt.show()."],"code":[{"lang":"python","text":"# Display the plots\nplt.show()"}]}],"commands":[],"reference":[{"path":"reference.py","text":"# Display the plots\nplt.show()"}],"source":"matplotlib/matplotlib · BSD 3-Clause"},"labex-matplotlib-3d-plots-as-subplots":{"intro":"In data analysis, it's often necessary to create 3D plots to visualize data. In Matplotlib, we can create 3D plots as subplots to compare different 3D data. This lab will demonstrate how to create 3D plots as subplots using Matplotlib.","steps":[{"title":"Import Libraries","body":["Before we start, we need to import the libraries that we will use in this lab. We will use Matplotlib, NumPy, and Axes3D from mpl_toolkits.mplot3d."],"code":[{"lang":"python","text":"import matplotlib.pyplot as plt\nimport numpy as np\nfrom mpl_toolkits.mplot3d import Axes3D"}]},{"title":"Create the Figure and Subplots","body":["Create the Figure and Subplots","We will create a figure with two subplots. The first subplot will be a 3D surface plot, and the second subplot will be a 3D wireframe plot."],"code":[{"lang":"python","text":"# Create a figure with two subplots\nfig = plt.figure(figsize=plt.figaspect(0.5))\n\n# Add the first subplot with 3D projection\nax1 = fig.add_subplot(1, 2, 1, projection='3d')\n\n# Add the second subplot with 3D projection\nax2 = fig.add_subplot(1, 2, 2, projection='3d')"}]},{"title":"Create the 3D Surface Plot","body":["We will create a 3D surface plot for the first subplot. We will use NumPy to create the data for the plot."],"code":[{"lang":"python","text":"# Create data for the 3D surface plot\nX = np.arange(-5, 5, 0.25)\nY = np.arange(-5, 5, 0.25)\nX, Y = np.meshgrid(X, Y)\nR = np.sqrt(X**2 + Y**2)\nZ = np.sin(R)\n\n# Plot the 3D surface plot\nsurf = ax1.plot_surface(X, Y, Z, cmap='coolwarm', linewidth=0, antialiased=False)\n\n# Add a color bar to the plot\nfig.colorbar(surf, shrink=0.5, aspect=10)\n\n# Set the limits for the z-axis\nax1.set_zlim(-1.01, 1.01)"}]},{"title":"Create the 3D Wireframe Plot","body":["We will create a 3D wireframe plot for the second subplot. We will use the get_test_data function from mpl_toolkits.mplot3d.axes3d to create the data for the plot."],"code":[{"lang":"python","text":"# Create data for the 3D wireframe plot\nX, Y, Z = Axes3D.get_test_data(0.05)\n\n# Plot the 3D wireframe plot\nax2.plot_wireframe(X, Y, Z, rstride=10, cstride=10)"}]},{"title":"Show the Plot","body":["We will use the plt.show() function to display the plot."],"code":[{"lang":"python","text":"plt.show()"}]}],"commands":[],"reference":[],"source":"matplotlib/matplotlib · BSD 3-Clause"},"labex-matplotlib-subplots-spacings-and-margins":{"intro":"In this lab, we will learn how to adjust the spacing of margins and subplots using pyplot.subplots_adjust in Python Matplotlib. This can be useful to improve the layout and aesthetics of our plots.","steps":[{"title":"Import Required Libraries","body":["First, we need to import the required libraries. For this tutorial, we will be using matplotlib.pyplot and numpy. Run the following code to import these libraries:"],"code":[{"lang":"python","text":"import matplotlib.pyplot as plt\nimport numpy as np"}]},{"title":"Create Plots","body":["Next, let's create two plots using imshow and random arrays generated by numpy.random. We will also add a color bar to the plots. Run the following code:"],"code":[{"lang":"python","text":"# Fixing random state for reproducibility\nnp.random.seed(19680801)\n\nplt.subplot(211)\nplt.imshow(np.random.random((100, 100)))\nplt.subplot(212)\nplt.imshow(np.random.random((100, 100)))\n\ncax = plt.axes([0.85, 0.1, 0.075, 0.8])\nplt.colorbar(cax=cax)\n\nplt.show()"}]},{"title":"Adjust Subplot Spacings and Margins","body":["Adjust Subplot Spacings and Margins","Now, let's adjust the subplot spacings and margins using pyplot.subplots_adjust. We can specify the values for the bottom, right, top, and left margins as fractions of the figure width and height. Run the following code:"],"code":[{"lang":"python","text":"plt.subplots_adjust(bottom=0.1, right=0.8, top=0.9)"}]},{"title":"Adjust Colorbar Position","body":["We can also adjust the position of the color bar using plt.axes. This function takes a list of [left, bottom, width, height] values as arguments to specify the position and size of the axes. Run the following code:"],"code":[{"lang":"python","text":"cax = plt.axes([0.85, 0.1, 0.075, 0.8])\nplt.colorbar(cax=cax)"}]},{"title":"Display the Plot","body":["Finally, let's display the plot using plt.show(). Run the following code:"],"code":[{"lang":"python","text":"plt.show()"}]}],"commands":[],"reference":[],"source":"matplotlib/matplotlib · BSD 3-Clause"},"labex-matplotlib-creating-subplots-with-matplotlib":{"intro":"Matplotlib is a popular data visualization library in Python. It provides a variety of functions to create different types of plots. One of its key features is the ability to create subplots. This allows users to create multiple plots in the same figure, making it easier to compare different data sets or views of the same data. In this lab, we will walk through the process of creating subplots using Matplotlib.","steps":[{"title":"Creating a Figure with a Single Subplot","body":["Creating a Figure with a Single Subplot","The simplest way to create a single subplot is by using the subplots() function without any arguments. This function returns a Figure object and a single Axes object."],"code":[{"lang":"python","text":"import matplotlib.pyplot as plt\n\nfig, ax = plt.subplots()"}]},{"title":"Stacking Subplots in One Direction","body":["Stacking Subplots in One Direction","To create multiple subplots stacked vertically or horizontally, we can pass the number of rows and columns as arguments to the subplots() function. The returned axs object is a 1D numpy array containing the list of created Axes."],"code":[{"lang":"python","text":"fig, axs = plt.subplots(2)\naxs[0].plot(x, y)\naxs[1].plot(x, -y)"}]},{"title":"Stacking Subplots in Two Directions","body":["Stacking Subplots in Two Directions","To create a grid of subplots, we can pass the number of rows and columns as arguments to the subplots() function. The returned axs object is a 2D NumPy array."],"code":[{"lang":"python","text":"fig, axs = plt.subplots(2, 2)\naxs[0, 0].plot(x, y)\naxs[0, 1].plot(x, y, 'tab:orange')\naxs[1, 0].plot(x, -y, 'tab:green')\naxs[1, 1].plot(x, -y, 'tab:red')"}]},{"title":"Sharing Axes","body":["By default, each Axes is scaled individually. To align the horizontal or vertical axis of subplots, we can use the sharex or sharey parameters."],"code":[{"lang":"python","text":"fig, (ax1, ax2) = plt.subplots(2, sharex=True)\nax1.plot(x, y)\nax2.plot(x + 1, -y)"}]},{"title":"Polar Axes","body":["We can create a grid of polar Axes by passing the projection='polar' parameter to the subplots() function."],"code":[{"lang":"python","text":"fig, (ax1, ax2) = plt.subplots(1, 2, subplot_kw=dict(projection='polar'))\nax1.plot(x, y)\nax2.plot(x, y ** 2)"}]}],"commands":[],"reference":[{"path":"reference.py","text":"fig, (ax1, ax2) = plt.subplots(1, 2, subplot_kw=dict(projection='polar'))\nax1.plot(x, y)\nax2.plot(x, y ** 2)"}],"source":"matplotlib/matplotlib · BSD 3-Clause"},"labex-matplotlib-3d-surface-plotting-with-matplotlib":{"intro":"This lab is a step-by-step tutorial on how to plot a 3D surface using Matplotlib in Python. The 3D surface is colored with the coolwarm colormap and made opaque by using 'antialiased=False'. The tutorial also demonstrates using the .LinearLocator and custom formatting for the z axis tick labels.","steps":[{"title":"Import Libraries","body":["We import the necessary libraries for the tutorial. Matplotlib is a plotting library for Python that provides an interface similar to MATLAB. Numpy is a fundamental package for scientific computing in Python."],"code":[{"lang":"python","text":"import matplotlib.pyplot as plt\nimport numpy as np\n\nfrom matplotlib import cm\nfrom matplotlib.ticker import LinearLocator"}]},{"title":"Create Figure and Axes","body":["We create a figure and axes with the subplot_kw parameter set to \"projection\": \"3d\". This will create a 3D projection of the plot."],"code":[{"lang":"python","text":"fig, ax = plt.subplots(subplot_kw={\"projection\": \"3d\"})"}]},{"title":"Create Data","body":["We create the data for the plot. We create the X and Y values as arrays with evenly spaced values from -5 to 5 in increments of 0.25. We then create a meshgrid of X and Y values using np.meshgrid(). We use the meshgrid to calculate the R values, which is the distance from the origin. We then calculate the Z values using the sin() function of R."],"code":[{"lang":"python","text":"X = np.arange(-5, 5, 0.25)\nY = np.arange(-5, 5, 0.25)\nX, Y = np.meshgrid(X, Y)\nR = np.sqrt(X**2 + Y**2)\nZ = np.sin(R)"}]},{"title":"Plot the Surface","body":["We plot the surface using the plot_surface() function. We pass in the X, Y, and Z values as well as the cmap parameter set to cm.coolwarm to color the surface with the coolwarm colormap. We also set linewidth=0 to remove the wireframe and antialiased=False to make the surface opaque."],"code":[{"lang":"python","text":"surf = ax.plot_surface(X, Y, Z, cmap=cm.coolwarm,\n                       linewidth=0, antialiased=False)"}]},{"title":"Customize the Z Axis","body":["We customize the z axis using the set_zlim() function to set the limits of the z axis to -1.01 to 1.01. We then use the set_major_locator() function to set the number of ticks on the z axis to 10 using LinearLocator(10). Finally, we use the set_major_formatter() function to format the z axis tick labels using a StrMethodFormatter."],"code":[{"lang":"python","text":"ax.set_zlim(-1.01, 1.01)\nax.zaxis.set_major_locator(LinearLocator(10))\n# A StrMethodFormatter is used automatically\nax.zaxis.set_major_formatter('{x:.02f}')"}]},{"title":"Add a Color Bar","body":["We add a color bar to the plot using the colorbar() function. We pass in the surf object and set shrink=0.5 and aspect=5 to adjust the size of the color bar."],"code":[{"lang":"python","text":"fig.colorbar(surf, shrink=0.5, aspect=5)"}]}],"commands":[],"reference":[{"path":"reference.py","text":"fig.colorbar(surf, shrink=0.5, aspect=5)"}],"source":"matplotlib/matplotlib · BSD 3-Clause"},"labex-matplotlib-creating-3d-surface-plots-with-matplotlib":{"intro":"This lab demonstrates how to create a 3D surface plot using Matplotlib in Python. The surface is plotted using a solid color. The lab will guide you through each step of the process, including creating the data, plotting the surface, and setting the aspect ratio.","steps":[{"title":"Importing Required Libraries","body":["The first step is to import the required libraries. In this lab, we are using Matplotlib and NumPy libraries."],"code":[{"lang":"python","text":"import matplotlib.pyplot as plt\nimport numpy as np"}]},{"title":"Creating Data","body":["The next step is to create the data for the 3D surface. We need to define u, v, x, y, and z. These variables will represent the angles and coordinates required to plot the surface. The linspace() function from NumPy is used to create the angles, and the outer() function is used to create the coordinates."],"code":[{"lang":"python","text":"# Make data\nu = np.linspace(0, 2 * np.pi, 100)\nv = np.linspace(0, np.pi, 100)\nx = 10 * np.outer(np.cos(u), np.sin(v))\ny = 10 * np.outer(np.sin(u), np.sin(v))\nz = 10 * np.outer(np.ones(np.size(u)), np.cos(v))"}]},{"title":"Creating the 3D Surface Plot","body":["Now we can create the 3D surface plot. We start by creating a figure and adding a subplot with the projection='3d' argument. Then, we use the plot_surface() function to plot the surface using the data we created in the previous step."],"code":[{"lang":"python","text":"# Plot the surface\nfig = plt.figure()\nax = fig.add_subplot(projection='3d')\nax.plot_surface(x, y, z)"}]},{"title":"Setting the Aspect Ratio","body":["To ensure that the plot has an equal aspect ratio, we can use the set_aspect() function. We pass in the string value 'equal' to set the aspect ratio to 1:1."],"code":[{"lang":"python","text":"# Set an equal aspect ratio\nax.set_aspect('equal')"}]}],"commands":[],"reference":[{"path":"reference.py","text":"# Set an equal aspect ratio\nax.set_aspect('equal')"}],"source":"matplotlib/matplotlib · BSD 3-Clause"},"labex-matplotlib-creating-customized-3d-surface-plots":{"intro":"In this lab, we will learn how to create a 3D surface plot with a checkerboard pattern using Python Matplotlib library. We will create a 3D surface plot, customize the colors of the surface, and adjust the limits of the z-axis.","steps":[{"title":"Import required libraries","body":["In this step, we will import the required libraries, which include matplotlib.pyplot, numpy, and LinearLocator from matplotlib.ticker."],"code":[{"lang":"python","text":"import matplotlib.pyplot as plt\nimport numpy as np\nfrom matplotlib.ticker import LinearLocator"}]},{"title":"Create data for the surface plot","body":["Create data for the surface plot","In this step, we will create data for the surface plot. We will create a meshgrid of X and Y values, calculate the radial distance R, and calculate the Z value based on the R value using np.sin()."],"code":[{"lang":"python","text":"# Create data for the surface plot\nX = np.arange(-5, 5, 0.25)\nxlen = len(X)\nY = np.arange(-5, 5, 0.25)\nylen = len(Y)\nX, Y = np.meshgrid(X, Y)\nR = np.sqrt(X**2 + Y**2)\nZ = np.sin(R)"}]},{"title":"Create colors for the surface plot","body":["Create colors for the surface plot","In this step, we will create colors for the surface plot. We will create an empty array of strings with the same shape as the meshgrid, and populate it with two colors in a checkerboard pattern."],"code":[{"lang":"python","text":"# Create colors for the surface plot\ncolortuple = ('y', 'b')\ncolors = np.empty(X.shape, dtype=str)\nfor y in range(ylen):\n    for x in range(xlen):\n        colors[y, x] = colortuple[(x + y) % len(colortuple)]"}]},{"title":"Create the surface plot","body":["In this step, we will create the surface plot with face colors taken from the array we made. We will also customize the z-axis."],"code":[{"lang":"python","text":"# Create the surface plot\nfig = plt.figure()\nax = fig.gca(projection='3d')\nsurf = ax.plot_surface(X, Y, Z, facecolors=colors, linewidth=0)\n\n# Customize the z axis\nax.set_zlim(-1, 1)\nax.zaxis.set_major_locator(LinearLocator(6))\n\n# Show the plot\nplt.show()"}]}],"commands":[],"reference":[{"path":"reference.py","text":"# Create the surface plot\nfig = plt.figure()\nax = fig.gca(projection='3d')\nsurf = ax.plot_surface(X, Y, Z, facecolors=colors, linewidth=0)\n\n# Customize the z axis\nax.set_zlim(-1, 1)\nax.zaxis.set_major_locator(LinearLocator(6))\n\n# Show the plot\nplt.show()"}],"source":"matplotlib/matplotlib · BSD 3-Clause"},"labex-matplotlib-3d-surface-plotting-with-polar-coordinates":{"intro":"This lab is a step-by-step guide to creating a 3D surface with polar coordinates using Python Matplotlib library. This lab assumes basic knowledge of Python programming and the Matplotlib library.","steps":[{"title":"Import Required Libraries","body":["We will begin by importing the required libraries for this lab, which include Matplotlib and NumPy. Matplotlib is a plotting library for Python, while NumPy is a library for the Python programming language, adding support for large, multi-dimensional arrays and matrices."],"code":[{"lang":"python","text":"import matplotlib.pyplot as plt\nimport numpy as np"}]},{"title":"Create the Mesh","body":["Next, we will create the mesh in polar coordinates and compute corresponding Z. We will create an array of radius values r, an array of angle values p, and then use NumPy's meshgrid() function to create a grid of R and P values. Finally, we will use the Z equation to compute the height of each point on the surface."],"code":[{"lang":"python","text":"r = np.linspace(0, 1.25, 50)\np = np.linspace(0, 2*np.pi, 50)\nR, P = np.meshgrid(r, p)\nZ = ((R**2 - 1)**2)"}]},{"title":"Express the Mesh in Cartesian System","body":["Express the Mesh in Cartesian System","Now, we will express the mesh in the cartesian system using NumPy's cos() and sin() functions."],"code":[{"lang":"python","text":"X, Y = R*np.cos(P), R*np.sin(P)"}]},{"title":"Plot the Surface","body":["In this step, we will plot the surface using Matplotlib's plot_surface() function. We will use the colormap YlGnBu_r to set the color of the surface."],"code":[{"lang":"python","text":"fig = plt.figure()\nax = fig.add_subplot(projection='3d')\nax.plot_surface(X, Y, Z, cmap=plt.cm.YlGnBu_r)"}]},{"title":"Tweak the Limits and Add Labels","body":["Tweak the Limits and Add Labels","Finally, we will tweak the limits of the plot and add axis labels using Matplotlib's set_zlim() and set_xlabel(), set_ylabel(), set_zlabel() functions. We will also use LaTeX math mode to write the axis labels."],"code":[{"lang":"python","text":"ax.set_zlim(0, 1)\nax.set_xlabel(r'$\\phi_\\mathrm{real}$')\nax.set_ylabel(r'$\\phi_\\mathrm{im}$')\nax.set_zlabel(r'$V(\\phi)$')"}]}],"commands":[],"reference":[{"path":"reference.py","text":"ax.set_zlim(0, 1)\nax.set_xlabel(r'$\\phi_\\mathrm{real}$')\nax.set_ylabel(r'$\\phi_\\mathrm{im}$')\nax.set_zlabel(r'$V(\\phi)$')"}],"source":"matplotlib/matplotlib · BSD 3-Clause"},"labex-matplotlib-matplotlib-svg-filter-line":{"intro":"This lab demonstrates how to use SVG filtering effects with Matplotlib. The filtering effects are only effective if your SVG renderer supports it.","steps":[{"title":"Import Required Libraries","body":["First, we need to import the required libraries: matplotlib.pyplot, io and xml.etree.ElementTree."],"code":[{"lang":"python","text":"import io\nimport xml.etree.ElementTree as ET\nimport matplotlib.pyplot as plt\nimport matplotlib.transforms as mtransforms"}]},{"title":"Create a Figure and Axes","body":["We create a figure object with plt.figure() and add an axes object using fig1.add_axes(). We also set the size and position of the axes using [0.1, 0.1, 0.8, 0.8]."],"code":[{"lang":"python","text":"fig1 = plt.figure()\nax = fig1.add_axes([0.1, 0.1, 0.8, 0.8])"}]},{"title":"Draw Lines","body":["We draw two lines using ax.plot(). We also customize the lines with different colors, markers, and labels."],"code":[{"lang":"python","text":"l1, = ax.plot([0.1, 0.5, 0.9], [0.1, 0.9, 0.5], \"bo-\", mec=\"b\", lw=5, ms=10, label=\"Line 1\")\nl2, = ax.plot([0.1, 0.5, 0.9], [0.5, 0.2, 0.7], \"rs-\", mec=\"r\", lw=5, ms=10, label=\"Line 2\")"}]},{"title":"Draw Shadows","body":["We draw shadows for the lines by using the same lines with a slight offset and gray colors. We adjust the color and zorder of the shadow lines so that they are drawn below the original lines. We also use the offset_copy() method to create an offset transform for the shadow lines."],"code":[{"lang":"python","text":"for l in [l1, l2]:\n    xx = l.get_xdata()\n    yy = l.get_ydata()\n    shadow, = ax.plot(xx, yy)\n    shadow.update_from(l)\n\n    shadow.set_color(\"0.2\")\n    shadow.set_zorder(l.get_zorder() - 0.5)\n\n    transform = mtransforms.offset_copy(l.get_transform(), fig1, x=4.0, y=-6.0, units='points')\n    shadow.set_transform(transform)\n\n    shadow.set_gid(l.get_label() + \"_shadow\")"}]},{"title":"Set Axes Limits and Save Figure","body":["Set Axes Limits and Save Figure","We set the x and y limits for the axes and save the figure as a bytes string in the SVG format using io.BytesIO() and plt.savefig()."],"code":[{"lang":"python","text":"ax.set_xlim(0., 1.)\nax.set_ylim(0., 1.)\n\nf = io.BytesIO()\nplt.savefig(f, format=\"svg\")"}]},{"title":"Define Filter","body":["We define a filter for a Gaussian blur using the <defs> and <filter> tags with the stdDeviation attribute."],"code":[{"lang":"python","text":"filter_def = \"\"\"\n  <defs xmlns='http://www.w3.org/2000/svg'\n        xmlns:xlink='http://www.w3.org/1999/xlink'>\n    <filter id='dropshadow' height='1.2' width='1.2'>\n      <feGaussianBlur result='blur' stdDeviation='3'/>\n    </filter>\n  </defs>\n\"\"\""}]},{"title":"Read and Modify SVG","body":["We read in the saved SVG using ET.XMLID() and insert the filter definition in the SVG DOM tree using tree.insert(). We then pick up the SVG element with the given ID and apply the shadow filter using shadow.set()."],"code":[{"lang":"python","text":"tree, xmlid = ET.XMLID(f.getvalue())\n\ntree.insert(0, ET.XML(filter_def))\n\nfor l in [l1, l2]:\n    shadow = xmlid[l.get_label() + \"_shadow\"]\n    shadow.set(\"filter\", 'url(#dropshadow)')\n\nfn = \"svg_filter_line.svg\"\nprint(f\"Saving '{fn}'\")\nET.ElementTree(tree).write(fn)"}]}],"commands":[],"reference":[{"path":"reference.py","text":"tree, xmlid = ET.XMLID(f.getvalue())\n\ntree.insert(0, ET.XML(filter_def))\n\nfor l in [l1, l2]:\n    shadow = xmlid[l.get_label() + \"_shadow\"]\n    shadow.set(\"filter\", 'url(#dropshadow)')\n\nfn = \"svg_filter_line.svg\"\nprint(f\"Saving '{fn}'\")\nET.ElementTree(tree).write(fn)"}],"source":"matplotlib/matplotlib · BSD 3-Clause"},"labex-matplotlib-matplotlib-pie-chart-filter":{"intro":"In this lab, we will demonstrate how to use filtering effects with Matplotlib's pie chart. We will use the pie chart drawing code borrowed from pie_demo.py and add filtering effects to the chart. The filtering effects are only effective if your SVG renderer supports it.","steps":[{"title":"Create a Pie Chart","body":["We will create a square figure and axes for our pie chart. We will define the labels and fracs for the chart. We will also set the explode values for the chart slices. Finally, we will draw the pie chart with the defined parameters."],"code":[{"lang":"python","text":"import matplotlib.pyplot as plt\nfrom matplotlib.patches import Shadow\n\nfig = plt.figure(figsize=(6, 6))\nax = fig.add_axes([0.1, 0.1, 0.8, 0.8])\n\nlabels = 'Frogs', 'Hogs', 'Dogs', 'Logs'\nfracs = [15, 30, 45, 10]\nexplode = (0, 0.05, 0, 0)\n\npies = ax.pie(fracs, explode=explode, labels=labels, autopct='%1.1f%%')\n\nfor w in pies[0]:\n    w.set_gid(w.get_label())\n    w.set_edgecolor(\"none\")\n\nfor w in pies[0]:\n    s = Shadow(w, -0.01, -0.01)\n    s.set_gid(w.get_gid() + \"_shadow\")\n    s.set_zorder(w.get_zorder() - 0.1)\n    ax.add_patch(s)\n\nplt.show()"}]},{"title":"Save the Chart as an SVG","body":["We will save the pie chart as an SVG file using the io and xml.etree.ElementTree modules. We will define the filter definition for the shadow using a Gaussian blur and lighting effect. The lighting filter is copied from http://www.w3.org/TR/SVG/filters.html. We will test the filter using Inkscape and Firefox3, but note that Inkscape's exporting may not support it."],"code":[{"lang":"python","text":"import io\nimport xml.etree.ElementTree as ET\n\nf = io.BytesIO()\nplt.savefig(f, format=\"svg\")\n\nfilter_def = \"\"\"\n  <defs xmlns='http://www.w3.org/2000/svg'\n        xmlns:xlink='http://www.w3.org/1999/xlink'>\n    <filter id='dropshadow' height='1.2' width='1.2'>\n      <feGaussianBlur result='blur' stdDeviation='2'/>\n    </filter>\n\n    <filter id='MyFilter' filterUnits='objectBoundingBox'\n            x='0' y='0' width='1' height='1'>\n      <feGaussianBlur in='SourceAlpha' stdDeviation='4%' result='blur'/>\n      <feOffset in='blur' dx='4%' dy='4%' result='offsetBlur'/>\n      <feSpecularLighting in='blur' surfaceScale='5' specularConstant='.75'\n           specularExponent='20' lighting-color='#bbbbbb' result='specOut'>\n        <fePointLight x='-5000%' y='-10000%' z='20000%'/>\n      </feSpecularLighting>\n      <feComposite in='specOut' in2='SourceAlpha'\n                   operator='in' result='specOut'/>\n      <feComposite in='SourceGraphic' in2='specOut' operator='arithmetic'\n    k1='0' k2='1' k3='1' k4='0'/>\n    </filter>\n  </defs>\n\"\"\"\n\ntree, xmlid = ET.XMLID(f.getvalue())\ntree.insert(0, ET.XML(filter_def))\n\nfor i, pie_name in enumerate(labels):\n    pie = xmlid[pie_name]\n    pie.set(\"filter\", 'url(#MyFilter)')\n\n    shadow = xmlid[pie_name + \"_shadow\"]\n    shadow.set(\"filter\", 'url(#dropshadow)')\n\nfn = \"svg_filter_pie.svg\"\nprint(f\"Saving '{fn}'\")\nET.ElementTree(tree).write(fn)"}]},{"title":"View the Pie Chart with Filtering Effects","body":["View the Pie Chart with Filtering Effects","We will view the pie chart with the filtering effects applied. We will use Inkscape to open the SVG file and view the pie chart with the filtering effects."],"code":[]},{"title":"Modify the Pie Chart with Different Filters","body":["Modify the Pie Chart with Different Filters","We can modify the pie chart with different filters by changing the filter definition. We can experiment with different filters to achieve different visual effects."],"code":[{"lang":"python","text":"filter_def = \"\"\"\n  <defs xmlns='http://www.w3.org/2000/svg'\n        xmlns:xlink='http://www.w3.org/1999/xlink'>\n    <filter id='dropshadow' height='1.2' width='1.2'>\n      <feGaussianBlur result='blur' stdDeviation='2'/>\n    </filter>\n\n    <filter id='MyFilter2' filterUnits='objectBoundingBox'\n            x='0' y='0' width='1' height='1'>\n      <feGaussianBlur in='SourceAlpha' stdDeviation='4%' result='blur'/>\n      <feOffset in='blur' dx='4%' dy='4%' result='offsetBlur'/>\n      <feSpecularLighting in='blur' surfaceScale='5' specularConstant='.75'\n           specularExponent='20' lighting-color='#bbbbbb' result='specOut'>\n        <fePointLight x='50%' y='50%' z='5000%'/>\n      </feSpecularLighting>\n      <feComposite in='specOut' in2='SourceAlpha'\n                   operator='in' result='specOut'/>\n      <feComposite in='SourceGraphic' in2='specOut' operator='arithmetic'\n    k1='0' k2='1' k3='1' k4='0'/>\n    </filter>\n  </defs>\n\"\"\"\n\ntree, xmlid = ET.XMLID(f.getvalue())\ntree.insert(0, ET.XML(filter_def))\n\nfor i, pie_name in enumerate(labels):\n    pie = xmlid[pie_name]\n    pie.set(\"filter\", 'url(#MyFilter2)')\n\n    shadow = xmlid[pie_name + \"_shadow\"]\n    shadow.set(\"filter\", 'url(#dropshadow)')\n\nfn = \"svg_filter_pie2.svg\"\nprint(f\"Saving '{fn}'\")\nET.ElementTree(tree).write(fn)"}]}],"commands":[],"reference":[{"path":"reference.py","text":"filter_def = \"\"\"\n  <defs xmlns='http://www.w3.org/2000/svg'\n        xmlns:xlink='http://www.w3.org/1999/xlink'>\n    <filter id='dropshadow' height='1.2' width='1.2'>\n      <feGaussianBlur result='blur' stdDeviation='2'/>\n    </filter>\n\n    <filter id='MyFilter2' filterUnits='objectBoundingBox'\n            x='0' y='0' width='1' height='1'>\n      <feGaussianBlur in='SourceAlpha' stdDeviation='4%' result='blur'/>\n      <feOffset in='blur' dx='4%' dy='4%' result='offsetBlur'/>\n      <feSpecularLighting in='blur' surfaceScale='5' specularConstant='.75'\n           specularExponent='20' lighting-color='#bbbbbb' result='specOut'>\n        <fePointLight x='50%' y='50%' z='5000%'/>\n      </feSpecularLighting>\n      <feComposite in='specOut' in2='SourceAlpha'\n                   operator='in' result='specOut'/>\n      <feComposite in='SourceGraphic' in2='specOut' operator='arithmetic'\n    k1='0' k2='1' k3='1' k4='0'/>\n    </filter>\n  </defs>\n\"\"\"\n\ntree, xmlid = ET.XMLID(f.getvalue())\ntree.insert(0, ET.XML(filter_def))\n\nfor i, pie_name in enumerate(labels):\n    pie = xmlid[pie_name]\n    pie.set(\"filter\", 'url(#MyFilter2)')\n\n    shadow = xmlid[pie_name + \"_shadow\"]\n    shadow.set(\"filter\", 'url(#dropshadow)')\n\nfn = \"svg_filter_pie2.svg\"\nprint(f\"Saving '{fn}'\")\nET.ElementTree(tree).write(fn)"}],"source":"matplotlib/matplotlib · BSD 3-Clause"},"labex-matplotlib-creating-an-interactive-histogram-with-matpl":{"intro":"In this lab, we will learn how to create an interactive histogram using Matplotlib. The interactivity is encoded in ECMAScript (JavaScript) and inserted in the SVG code in a post-processing step. The resulting histogram will have bars that can be hidden or shown by clicking on legend markers.","steps":[{"title":"Create the Histogram, Legend, and Title","body":["Create the Histogram, Legend, and Title","First, we will create the histogram, legend, and title using Matplotlib. We will also assign IDs to each object using the set_gid() method. This will help relate Matplotlib objects created in Python and the corresponding SVG constructs that are parsed in the second step."],"code":[{"lang":"python","text":"import matplotlib.pyplot as plt\nimport numpy as np\n\n# Fixing random state for reproducibility\nnp.random.seed(19680801)\n\n# Create histogram, legend, and title\nplt.figure()\nr = np.random.randn(100)\nr1 = r + 1\nlabels = ['Rabbits', 'Frogs']\nH = plt.hist([r, r1], label=labels)\ncontainers = H[-1]\nleg = plt.legend(frameon=False)\nplt.title(\"From a web browser, click on the legend\\n\"\n          \"marker to toggle the corresponding histogram.\")\n\n# Assign IDs to the SVG objects we'll modify\nhist_patches = {}\nfor ic, c in enumerate(containers):\n    hist_patches[f'hist_{ic}'] = []\n    for il, element in enumerate(c):\n        element.set_gid(f'hist_{ic}_patch_{il}')\n        hist_patches[f'hist_{ic}'].append(f'hist_{ic}_patch_{il}')\n\n# Set IDs for the legend patches\nfor i, t in enumerate(leg.get_patches()):\n    t.set_gid(f'leg_patch_{i}')\n\n# Set IDs for the text patches\nfor i, t in enumerate(leg.get_texts()):\n    t.set_gid(f'leg_text_{i}')"}]},{"title":"Add Interactivity to the Histogram","body":["Add Interactivity to the Histogram","Next, we will add interactivity to the histogram by modifying the SVG code using ECMAScript (JavaScript). We will add attributes to the patch and text objects using the set() method. We will also create a global variable container that stores the patches ID belonging to each histogram. Finally, we will create a function toggle_hist() that sets the visibility attribute of all patches of each histogram and the opacity of the marker itself."],"code":[{"lang":"python","text":"from io import BytesIO\nimport json\nimport xml.etree.ElementTree as ET\n\nplt.rcParams['svg.fonttype'] = 'none'\n\n# Save SVG in a fake file object\nf = BytesIO()\nplt.savefig(f, format=\"svg\")\n\n# Create XML tree from the SVG file\ntree, xmlid = ET.XMLID(f.getvalue())\n\n# Add attributes to the patch objects\nfor i, t in enumerate(leg.get_patches()):\n    el = xmlid[f'leg_patch_{i}']\n    el.set('cursor', 'pointer')\n    el.set('onclick', \"toggle_hist(this)\")\n\n# Add attributes to the text objects\nfor i, t in enumerate(leg.get_texts()):\n    el = xmlid[f'leg_text_{i}']\n    el.set('cursor', 'pointer')\n    el.set('onclick', \"toggle_hist(this)\")\n\n# Create script defining the function `toggle_hist`\nscript = \"\"\"\n<script type=\"text/ecmascript\">\n<![CDATA[\nvar container = %s\n\nfunction toggle(oid, attribute, values) {\n    /* Toggle the style attribute of an object between two values.\n\n    Parameters\n    ----------\n    oid : str\n      Object identifier.\n    attribute : str\n      Name of style attribute.\n    values : [on state, off state]\n      The two values that are switched between.\n    */\n    var obj = document.getElementById(oid);\n    var a = obj.style[attribute];\n\n    a = (a == values[0] || a == \"\") ? values[1] : values[0];\n    obj.style[attribute] = a;"}]},{"title":"View the Interactive Histogram","body":["View the Interactive Histogram"],"code":[]}],"commands":[],"reference":[],"source":"matplotlib/matplotlib · BSD 3-Clause"},"labex-matplotlib-matplotlib-svg-tooltip":{"intro":"This lab is a step-by-step tutorial on how to create a tooltip that will show up when hovering over a matplotlib patch. We will create the tooltip in matplotlib and simply toggle its visibility on when hovering over the patch. This approach provides total control over the tooltip placement and appearance, at the expense of more code up front.","steps":[{"title":"Create the patches","body":["We first create patches to which tooltips will be assigned."],"code":[{"lang":"python","text":"rect1 = plt.Rectangle((10, -20), 10, 5, fc='blue')\nrect2 = plt.Rectangle((-20, 15), 10, 5, fc='green')\n\nshapes = [rect1, rect2]\nlabels = ['This is a blue rectangle.', 'This is a green rectangle']"}]},{"title":"Add patches and tooltip annotations","body":["Add patches and tooltip annotations","We then add the patches and tooltip annotations to the plot. The tooltip annotations are created using the annotate method. We set the xy parameter to the coordinates of the patch and xytext to (0, 0) to position the tooltip directly over the patch. We also set the textcoords parameter to 'offset points' to align the tooltip with the patch. We set the color parameter to 'w' to make the text white, ha to 'center' to center the text horizontally, fontsize to 8 to set the font size, and bbox to set the style of the tooltip box."],"code":[{"lang":"python","text":"for i, (item, label) in enumerate(zip(shapes, labels)):\n    patch = ax.add_patch(item)\n    annotate = ax.annotate(labels[i], xy=item.get_xy(), xytext=(0, 0),\n                           textcoords='offset points', color='w', ha='center',\n                           fontsize=8, bbox=dict(boxstyle='round, pad=.5',\n                                                 fc=(.1, .1, .1, .92),\n                                                 ec=(1., 1., 1.), lw=1,\n                                                 zorder=1))\n\n    ax.add_patch(patch)\n    patch.set_gid(f'mypatch_{i:03d}')\n    annotate.set_gid(f'mytooltip_{i:03d}')"}]},{"title":"Save the figure as SVG","body":["We save the figure in a fake file object using the BytesIO class and the savefig method."],"code":[{"lang":"python","text":"ax.set_xlim(-30, 30)\nax.set_ylim(-30, 30)\nax.set_aspect('equal')\n\nf = BytesIO()\nplt.savefig(f, format=\"svg\")"}]},{"title":"Add interactivity","body":["We add interactivity to the plot by creating a tooltip that will be toggled on and off when hovering over the patches. We do this by creating an XML tree from the SVG file, hiding the tooltips, and assigning onmouseover and onmouseout callbacks to the patches. We also define the ShowTooltip and HideTooltip functions that will be called when hovering over the patches."],"code":[{"lang":"python","text":"tree, xmlid = ET.XMLID(f.getvalue())\ntree.set('onload', 'init(event)')\n\nfor i in shapes:\n    # Get the index of the shape\n    index = shapes.index(i)\n    # Hide the tooltips\n    tooltip = xmlid[f'mytooltip_{index:03d}']\n    tooltip.set('visibility', 'hidden')\n    # Assign onmouseover and onmouseout callbacks to patches.\n    mypatch = xmlid[f'mypatch_{index:03d}']\n    mypatch.set('onmouseover', \"ShowTooltip(this)\")\n    mypatch.set('onmouseout', \"HideTooltip(this)\")\n\n# This is the script defining the ShowTooltip and HideTooltip functions.\nscript = \"\"\"\n    <script type=\"text/ecmascript\">\n    <![CDATA[\n\n    function init(event) {\n        if ( window.svgDocument == null ) {\n            svgDocument = event.target.ownerDocument;\n            }\n        }\n\n    function ShowTooltip(obj) {\n        var cur = obj.id.split(\"_\")[1];\n        var tip = svgDocument.getElementById('mytooltip_' + cur);\n        tip.setAttribute('visibility', \"visible\")\n        }\n\n    function HideTooltip(obj) {\n        var cur = obj.id.split(\"_\")[1];\n        var tip = svgDocument.getElementById('mytooltip_' + cur);\n        tip.setAttribute('visibility', \"hidden\")\n        }\n\n    ]]>\n    </script>\n    \"\"\"\n\n# Insert the script at the top of the file and save it.\ntree.insert(0, ET.XML(script))\nET.ElementTree(tree).write('svg_tooltip.svg')"}]}],"commands":[],"reference":[{"path":"reference.py","text":"tree, xmlid = ET.XMLID(f.getvalue())\ntree.set('onload', 'init(event)')\n\nfor i in shapes:\n    # Get the index of the shape\n    index = shapes.index(i)\n    # Hide the tooltips\n    tooltip = xmlid[f'mytooltip_{index:03d}']\n    tooltip.set('visibility', 'hidden')\n    # Assign onmouseover and onmouseout callbacks to patches.\n    mypatch = xmlid[f'mypatch_{index:03d}']\n    mypatch.set('onmouseover', \"ShowTooltip(this)\")\n    mypatch.set('onmouseout', \"HideTooltip(this)\")\n\n# This is the script defining the ShowTooltip and HideTooltip functions.\nscript = \"\"\"\n    <script type=\"text/ecmascript\">\n    <![CDATA[\n\n    function init(event) {\n        if ( window.svgDocument == null ) {\n            svgDocument = event.target.ownerDocument;\n            }\n        }\n\n    function ShowTooltip(obj) {\n        var cur = obj.id.split(\"_\")[1];\n        var tip = svgDocument.getElementById('mytooltip_' + cur);\n        tip.setAttribute('visibility', \"visible\")\n        }\n\n    function HideTooltip(obj) {\n        var cur = obj.id.split(\"_\")[1];\n        var tip = svgDocument.getElementById('mytooltip_' + cur);\n        tip.setAttribute('visibility', \"hidden\")\n        }\n\n    ]]>\n    </script>\n    \"\"\"\n\n# Insert the script at the top of the file and save it.\ntree.insert(0, ET.XML(script))\nET.ElementTree(tree).write('svg_tooltip.svg')"}],"source":"matplotlib/matplotlib · BSD 3-Clause"},"labex-matplotlib-matplotlib-symmetric-log-plots":{"intro":"Matplotlib is a data visualization library that is widely used in Python. It allows users to create a wide variety of visualizations, including line plots, scatter plots, bar charts, and more. In this lab, you will learn how to use the symlog axis scaling in Matplotlib to create symmetric log plots.","steps":[{"title":"Import Libraries","body":["Before we can begin, we need to import the necessary libraries. In this lab, we will be using Matplotlib and NumPy."],"code":[{"lang":"python","text":"import matplotlib.pyplot as plt\nimport numpy as np"}]},{"title":"Generate Data","body":["Next, we need to generate some data to plot. In this example, we will create three arrays: one for the x-axis values, one for the y-axis values in the first plot, and one for the y-axis values in the third plot."],"code":[{"lang":"python","text":"dt = 0.01\nx = np.arange(-50.0, 50.0, dt)\ny1 = np.arange(0, 100.0, dt)\ny3 = np.sin(x / 3.0)"}]},{"title":"Create Plots","body":["Now that we have our data, we can create our plots. We will create three subplots, each with a different symlog axis scaling."],"code":[{"lang":"python","text":"fig, (ax0, ax1, ax2) = plt.subplots(nrows=3)"}]},{"title":"Create Symlog Plot on x-axis","body":["In the first subplot, we will create a symlog plot on the x-axis. We will also add a minor grid to the x-axis."],"code":[{"lang":"python","text":"ax0.plot(x, y1)\nax0.set_xscale('symlog')\nax0.set_ylabel('symlogx')\nax0.grid()\nax0.xaxis.grid(which='minor')"}]},{"title":"Create Symlog Plot on y-axis","body":["In the second subplot, we will create a symlog plot on the y-axis."],"code":[{"lang":"python","text":"ax1.plot(y1, x)\nax1.set_yscale('symlog')\nax1.set_ylabel('symlogy')"}]},{"title":"Create Symlog Plot on both x-axis and y-axis","body":["Create Symlog Plot on both x-axis and y-axis","In the third subplot, we will create a symlog plot on both the x-axis and y-axis. We will also set the linthresh parameter to 0.015."],"code":[{"lang":"python","text":"ax2.plot(x, y3)\nax2.set_xscale('symlog')\nax2.set_yscale('symlog', linthresh=0.015)\nax2.grid()\nax2.set_ylabel('symlog both')"}]},{"title":"Display the Plots","body":["Finally, we can display our plots using the show() method."],"code":[{"lang":"python","text":"plt.show()"}]}],"commands":[],"reference":[],"source":"matplotlib/matplotlib · BSD 3-Clause"},"labex-matplotlib-matplotlib-table-function":{"intro":"In this lab, we will learn how to use the Matplotlib table function to display a table within a plot. We will use a sample dataset to visualize the loss incurred by different natural disasters over the years.","steps":[{"title":"Import Required Libraries","body":["We will begin by importing the necessary libraries for the project. We will use the Matplotlib library to create the table."],"code":[{"lang":"python","text":"import matplotlib.pyplot as plt\nimport numpy as np"}]},{"title":"Create the Dataset","body":["Next, we will create a sample dataset to visualize the loss incurred by different natural disasters over the years. We will use a two-dimensional list to store the data and a tuple to store the column names."],"code":[{"lang":"python","text":"data = [[ 66386, 174296,  75131, 577908,  32015],\n        [ 58230, 381139,  78045,  99308, 160454],\n        [ 89135,  80552, 152558, 497981, 603535],\n        [ 78415,  81858, 150656, 193263,  69638],\n        [139361, 331509, 343164, 781380,  52269]]\n\ncolumns = ('Freeze', 'Wind', 'Flood', 'Quake', 'Hail')"}]},{"title":"Create Row Labels","body":["We will create row labels for the dataset to represent the number of years for which the loss has been recorded. We will use a list comprehension to create the row labels."],"code":[{"lang":"python","text":"rows = ['%d year' % x for x in (100, 50, 20, 10, 5)]"}]},{"title":"Create Color Scheme","body":["We will create a color scheme for the table using the plt.cm.BuPu function. We will use a pastel shade of blue and purple colors for the rows."],"code":[{"lang":"python","text":"colors = plt.cm.BuPu(np.linspace(0, 0.5, len(rows)))"}]},{"title":"Create Vertical Stacked Bar Chart","body":["Create Vertical Stacked Bar Chart","We will create a vertical stacked bar chart using the plt.bar function to represent the loss incurred by different natural disasters over the years. We will use a for loop to iterate over each row of data and plot the bars."],"code":[{"lang":"python","text":"n_rows = len(data)\n\nindex = np.arange(len(columns)) + 0.3\nbar_width = 0.4\n\ny_offset = np.zeros(len(columns))\n\ncell_text = []\nfor row in range(n_rows):\n    plt.bar(index, data[row], bar_width, bottom=y_offset, color=colors[row])\n    y_offset = y_offset + data[row]\n    cell_text.append(['%1.1f' % (x / 1000.0) for x in y_offset])"}]},{"title":"Reverse Colors and Text Labels","body":["Reverse Colors and Text Labels","We will reverse the colors and text labels of the table to display the last value at the top using the [::-1] function."],"code":[{"lang":"python","text":"colors = colors[::-1]\ncell_text.reverse()"}]},{"title":"Add Table to the Plot","body":["We will add a table to the bottom of the plot using the plt.table function. We will pass the cell text, row labels, row colors, and column labels as parameters to the function."],"code":[{"lang":"python","text":"the_table = plt.table(cellText=cell_text,\n                      rowLabels=rows,\n                      rowColours=colors,\n                      colLabels=columns,\n                      loc='bottom')"}]},{"title":"Adjust Plot Layout","body":["We will adjust the layout of the plot to make room for the table using the plt.subplots_adjust function."],"code":[{"lang":"python","text":"plt.subplots_adjust(left=0.2, bottom=0.2)"}]}],"commands":[],"reference":[],"source":"matplotlib/matplotlib · BSD 3-Clause"},"labex-matplotlib-matplotlib-visualization-techniques-for-data":{"intro":"In this lab, you will learn how to use Matplotlib library to create various plots. Matplotlib is a Python library used for visualizing data. It is built on top of the NumPy and SciPy libraries and allows you to create a wide range of visualizations such as line charts, scatter plots, and bar charts.","steps":[{"title":"Import Matplotlib and Numpy libraries","body":["Import Matplotlib and Numpy libraries","Before we can start creating plots, we need to import the Matplotlib and Numpy libraries. We can do this by running the following code:"],"code":[{"lang":"python","text":"import matplotlib.pyplot as plt\nimport numpy as np"}]},{"title":"Create a Simple Line Plot","body":["In this step, we will create a simple line plot using Matplotlib. We will start by generating some data to plot using the NumPy linspace() function and the cos() function. Then, we will use the plot() function to create the plot."],"code":[{"lang":"python","text":"t = np.linspace(0.0, 1.0, 100)\ns = np.cos(4 * np.pi * t) + 2\n\nplt.plot(t, s)\nplt.show()"}]},{"title":"Customize the Plot","body":["In this step, we will customize the plot by adding labels to the x and y axes, and a title to the plot."],"code":[{"lang":"python","text":"plt.plot(t, s)\n\nplt.xlabel('time (s)')\nplt.ylabel('Velocity (degrees/sec)')\nplt.title('Cosine Wave')\nplt.show()"}]},{"title":"Create a Scatter Plot","body":["In this step, we will create a scatter plot using Matplotlib. We will start by generating some random data to plot using the NumPy random() function. Then, we will use the scatter() function to create the plot."],"code":[{"lang":"python","text":"x = np.random.randn(100)\ny = np.random.randn(100)\n\nplt.scatter(x, y)\nplt.show()"}]},{"title":"Create a Bar Chart","body":["In this step, we will create a bar chart using Matplotlib. We will start by generating some data to plot using the NumPy random() function. Then, we will use the bar() function to create the plot."],"code":[{"lang":"python","text":"x = ['A', 'B', 'C', 'D', 'E']\ny = np.random.randint(1, 10, 5)\n\nplt.bar(x, y)\nplt.show()"}]}],"commands":[],"reference":[{"path":"reference.py","text":"x = ['A', 'B', 'C', 'D', 'E']\ny = np.random.randint(1, 10, 5)\n\nplt.bar(x, y)\nplt.show()"}],"source":"matplotlib/matplotlib · BSD 3-Clause"},"labex-matplotlib-text-alignment-in-matplotlib":{"intro":"Matplotlib is a plotting library for the Python programming language and its numerical mathematics extension NumPy. This tutorial will focus on text alignment in Matplotlib.","steps":[{"title":"Creating a Rectangle","body":["We will begin by creating a rectangle in the plot using Rectangle() function of matplotlib.patches module. After creating the rectangle, we will set its horizontal and vertical limits using set_xlim() and set_ylim() functions. Finally, we will add the rectangle to the plot."],"code":[{"lang":"python","text":"import matplotlib.pyplot as plt\nfrom matplotlib.patches import Rectangle\n\nfig, ax = plt.subplots()\n\n# Build a rectangle in axes coords\nleft, width = .25, .5\nbottom, height = .25, .5\nright = left + width\ntop = bottom + height\np = Rectangle((left, bottom), width, height, fill=False)\nax.add_patch(p)\n\n# Set the horizontal and vertical limits\nax.set_xlim(0, 1)\nax.set_ylim(0, 1)\nplt.show()"}]},{"title":"Adding Text to the Rectangle","body":["In this step, we will add text to the rectangle using the text() function. The horizontal and vertical alignment of the text will be set using the horizontalalignment and verticalalignment parameters respectively."],"code":[{"lang":"python","text":"# Add text to the rectangle\nax.text(left, bottom, 'left top',\n        horizontalalignment='left',\n        verticalalignment='top',\n        transform=ax.transAxes)\n\nax.text(left, bottom, 'left bottom',\n        horizontalalignment='left',\n        verticalalignment='bottom',\n        transform=ax.transAxes)\n\nax.text(right, top, 'right bottom',\n        horizontalalignment='right',\n        verticalalignment='bottom',\n        transform=ax.transAxes)\n\nax.text(right, top, 'right top',\n        horizontalalignment='right',\n        verticalalignment='top',\n        transform=ax.transAxes)\n\nax.text(right, bottom, 'center top',\n        horizontalalignment='center',\n        verticalalignment='top',\n        transform=ax.transAxes)\n\nax.text(left, 0.5 * (bottom + top), 'right center',\n        horizontalalignment='right',\n        verticalalignment='center',\n        rotation='vertical',\n        transform=ax.transAxes)\n\nax.text(left, 0.5 * (bottom + top), 'left center',\n        horizontalalignment='left',\n        verticalalignment='center',\n        rotation='vertical',\n        transform=ax.transAxes)\n\nax.text(0.5 * (left + right), 0.5 * (bottom + top), 'middle',\n        horizontalalignment='center',\n        verticalalignment='center',\n        transform=ax.transAxes)\n\nax.text(right, 0.5 * (bottom + top), 'centered',\n        horizontalalignment='center',\n        verticalalignment='center',\n        rotation='vertical',\n        transform=ax.transAxes)"}]},{"title":"Customizing the Plot","body":["In this step, we will customize the plot by adding axis labels and removing the axis lines."],"code":[{"lang":"python","text":"# Customize the plot\nax.set_axis_off()\nax.set_xlabel('X Label')\nax.set_ylabel('Y Label')\nax.set_title('Text Alignment in Matplotlib')\nplt.show()"}]}],"commands":[],"reference":[{"path":"reference.py","text":"# Customize the plot\nax.set_axis_off()\nax.set_xlabel('X Label')\nax.set_ylabel('Y Label')\nax.set_title('Text Alignment in Matplotlib')\nplt.show()"}],"source":"matplotlib/matplotlib · BSD 3-Clause"},"labex-matplotlib-matplotlib-text-commands":{"intro":"Matplotlib is a Python library used to create visualizations such as line plots, scatter plots, bar plots, and more. In this lab, we will learn how to use text commands to add text to our plots. We will explore different ways to add text and annotations to our plots.","steps":[{"title":"Importing Required Libraries","body":["First, we need to import the matplotlib library and its pyplot module. We will use the pyplot module to create and customize our plots."],"code":[{"lang":"python","text":"import matplotlib.pyplot as plt"}]},{"title":"Creating a Figure and Subplot","body":["We will create a figure and subplot using the plt.subplots() function. This function returns a tuple that contains a figure and a subplot. We will use the subplot to add text and annotations to our plot."],"code":[{"lang":"python","text":"fig, ax = plt.subplots()"}]},{"title":"Adding a Title to the Figure","body":["We can add a title to the figure using the fig.suptitle() function. This function takes a string as an argument and sets the title of the figure."],"code":[{"lang":"python","text":"fig.suptitle('bold figure suptitle', fontsize=14, fontweight='bold')"}]},{"title":"Adding a Title to the Subplot","body":["We can add a title to the subplot using the ax.set_title() function. This function takes a string as an argument and sets the title of the subplot."],"code":[{"lang":"python","text":"ax.set_title('axes title')"}]},{"title":"Adding Labels to the Axes","body":["We can add labels to the x and y axes using the ax.set_xlabel() and ax.set_ylabel() functions, respectively. These functions take a string as an argument and set the label of the corresponding axis."],"code":[{"lang":"python","text":"ax.set_xlabel('xlabel')\nax.set_ylabel('ylabel')"}]},{"title":"Adding Text to the Plot","body":["We can add text to the plot using the ax.text() function. This function takes three arguments: the x-coordinate, the y-coordinate, and the text string. We can customize the text style using the style, bbox, and fontsize arguments."],"code":[{"lang":"python","text":"ax.text(3, 8, 'boxed italics text in data coords', style='italic',\n        bbox={'facecolor': 'red', 'alpha': 0.5, 'pad': 10})\n\nax.text(2, 6, r'an equation: $E=mc^2$', fontsize=15)\n\nax.text(3, 2, 'Unicode: Institut f\\374r Festk\\366rperphysik')\n\nax.text(0.95, 0.01, 'colored text in axes coords',\n        verticalalignment='bottom', horizontalalignment='right',\n        transform=ax.transAxes,\n        color='green', fontsize=15)"}]},{"title":"Adding Annotations to the Plot","body":["Adding Annotations to the Plot","We can add annotations to the plot using the ax.annotate() function. This function takes three arguments: the annotation text, the xy-coordinate of the point to annotate, and the xy-coordinate of the text position. We can customize the annotation style using the arrowprops argument."],"code":[{"lang":"python","text":"ax.annotate('annotate', xy=(2, 1), xytext=(3, 4),\n            arrowprops=dict(facecolor='black', shrink=0.05))"}]},{"title":"Setting the Plot Limits","body":["We can set the x and y limits of the plot using the ax.set() function. This function takes two arguments: the x and y limits as tuples."],"code":[{"lang":"python","text":"ax.set(xlim=(0, 10), ylim=(0, 10))"}]}],"commands":[],"reference":[],"source":"matplotlib/matplotlib · BSD 3-Clause"},"labex-matplotlib-customize-text-styling-in-matplotlib-plots":{"intro":"In this lab, we will learn how to control the style of text and labels in a Matplotlib plot using a dictionary. By creating a dictionary of options, we can share parameters across multiple text objects and labels. This will allow us to easily customize the font family, color, weight, and size of text in our plots.","steps":[{"title":"Import the Necessary Libraries","body":["Import the Necessary Libraries","We will start by importing the necessary libraries for this tutorial. We will be using Matplotlib and NumPy."],"code":[{"lang":"python","text":"import matplotlib.pyplot as plt\nimport numpy as np"}]},{"title":"Define the Font Dictionary","body":["Next, we will define the font dictionary that will contain the style options for our text and labels. In this example, we will set the font family to 'serif', the color to 'darkred', the weight to 'normal', and the size to 16."],"code":[{"lang":"python","text":"font = {'family': 'serif',\n        'color':  'darkred',\n        'weight': 'normal',\n        'size': 16,\n        }"}]},{"title":"Create the Plot","body":["Now, we can create our plot. We will generate some data using NumPy and plot a damped exponential decay curve."],"code":[{"lang":"python","text":"x = np.linspace(0.0, 5.0, 100)\ny = np.cos(2*np.pi*x) * np.exp(-x)\n\nplt.plot(x, y, 'k')"}]},{"title":"Customize the Title","body":["We can customize the title of our plot using the font dictionary that we defined earlier. We will set the fontdict parameter of the title() function to our font dictionary."],"code":[{"lang":"python","text":"plt.title('Damped Exponential Decay', fontdict=font)"}]},{"title":"Add Text to the Plot","body":["We can add text to our plot using the text() function. In this example, we will add a LaTeX expression to the plot using the font dictionary to customize the style."],"code":[{"lang":"python","text":"plt.text(2, 0.65, r'$\\cos(2 \\pi t) \\exp(-t)$', fontdict=font)"}]},{"title":"Customize the Axis Labels","body":["We can customize the axis labels of our plot using the font dictionary as well. We will set the fontdict parameter of the xlabel() and ylabel() functions to our font dictionary."],"code":[{"lang":"python","text":"plt.xlabel('Time (s)', fontdict=font)\nplt.ylabel('Voltage (mV)', fontdict=font)"}]},{"title":"Adjust the Spacing","body":["Finally, we can adjust the spacing of our plot to prevent the clipping of the ylabel. We will use the subplots_adjust() function to adjust the left margin."],"code":[{"lang":"python","text":"plt.subplots_adjust(left=0.15)"}]}],"commands":[],"reference":[{"path":"reference.py","text":"plt.subplots_adjust(left=0.15)"}],"source":"matplotlib/matplotlib · BSD 3-Clause"},"labex-matplotlib-text-annotations-in-3d":{"intro":"This lab will demonstrate how to place text annotations on a 3D plot using Matplotlib library in Python. The following functionalities will be covered:","steps":[{"title":"Import Libraries","body":["Import the necessary libraries to create a 3D plot and add text annotations."],"code":[{"lang":"python","text":"import matplotlib.pyplot as plt"}]},{"title":"Create a 3D Plot","body":["Create a 3D plot using the add_subplot method."],"code":[{"lang":"python","text":"ax = plt.figure().add_subplot(projection='3d')"}]},{"title":"Using ~.Axes3D.text Function with zdir Values","body":["Using ~.Axes3D.text Function with zdir Values","Use the ~.Axes3D.text function to place text annotations with different zdir values."],"code":[{"lang":"python","text":"zdirs = (None, 'x', 'y', 'z', (1, 1, 0), (1, 1, 1))\nxs = (1, 4, 4, 9, 4, 1)\nys = (2, 5, 8, 10, 1, 2)\nzs = (10, 3, 8, 9, 1, 8)\n\nfor zdir, x, y, z in zip(zdirs, xs, ys, zs):\n    label = '(%d, %d, %d), dir=%s' % (x, y, z, zdir)\n    ax.text(x, y, z, label, zdir)"}]},{"title":"Using ~.Axes3D.text Function with color Keyword","body":["Using ~.Axes3D.text Function with color Keyword","Use the ~.Axes3D.text function with the color keyword to change the color of the text annotation."],"code":[{"lang":"python","text":"ax.text(9, 0, 0, \"red\", color='red')"}]},{"title":"Using .text2D Function","body":["Use the .text2D function to place text annotations on a fixed position on the ax object."],"code":[{"lang":"python","text":"ax.text2D(0.05, 0.95, \"2D Text\", transform=ax.transAxes)"}]},{"title":"Tweaking Display Region and Labels","body":["Tweaking Display Region and Labels","Tweak the display region and labels of the 3D plot."],"code":[{"lang":"python","text":"ax.set_xlim(0, 10)\nax.set_ylim(0, 10)\nax.set_zlim(0, 10)\nax.set_xlabel('X axis')\nax.set_ylabel('Y axis')\nax.set_zlabel('Z axis')"}]},{"title":"Display the Plot","body":["Display the 3D plot with text annotations."],"code":[{"lang":"python","text":"plt.show()"}]}],"commands":[],"reference":[],"source":"matplotlib/matplotlib · BSD 3-Clause"},"labex-matplotlib-interactive-plotting-with-textbox":{"intro":"In this tutorial, we will learn how to create an interactive plot with a textbox using Matplotlib. The Textbox widget allows users to provide text input, which updates the plot in real-time.","steps":[{"title":"Import Required Libraries","body":["First, we need to import the necessary libraries. We will be using NumPy and Matplotlib to create the plot and the Textbox widget."],"code":[{"lang":"python","text":"import matplotlib.pyplot as plt\nimport numpy as np\nfrom matplotlib.widgets import TextBox"}]},{"title":"Create the Initial Plot","body":["Next, we create the initial plot that will be updated based on the user's input. In this example, we create a plot of a function with t as the independent variable."],"code":[{"lang":"python","text":"fig, ax = plt.subplots()\nfig.subplots_adjust(bottom=0.2)\n\nt = np.arange(-2.0, 2.0, 0.001)\nl, = ax.plot(t, np.zeros_like(t), lw=2)"}]},{"title":"Define the Submit Function","body":["We define the submit function that will be called when the user submits the text input. This function updates the plotted function based on the user's input."],"code":[{"lang":"python","text":"def submit(expression):\n    \"\"\"\n    Update the plotted function to the new math *expression*.\n\n    *expression* is a string using \"t\" as its independent variable, e.g.\n    \"t ** 3\".\n    \"\"\"\n    ydata = eval(expression, {'np': np}, {'t': t})\n    l.set_ydata(ydata)\n    ax.relim()\n    ax.autoscale_view()\n    plt.draw()"}]},{"title":"Create the Textbox Widget","body":["We create the Textbox widget and add it to the figure. The on_submit method is used to trigger the submit function when the user presses enter in the textbox or leaves the textbox. We also set the initial value of the Textbox widget to t ** 2."],"code":[{"lang":"python","text":"axbox = fig.add_axes([0.1, 0.05, 0.8, 0.075])\ntext_box = TextBox(axbox, \"Evaluate\", textalignment=\"center\")\ntext_box.on_submit(submit)\ntext_box.set_val(\"t ** 2\")  # Trigger `submit` with the initial string."}]},{"title":"Display the Plot","body":["Finally, we display the plot to the user."],"code":[{"lang":"python","text":"plt.show()"}]}],"commands":[],"reference":[],"source":"matplotlib/matplotlib · BSD 3-Clause"},"labex-matplotlib-matplotlib-tick-formatter-tutorial":{"intro":"Matplotlib is a widely used Python plotting library that produces high quality 2D and 3D graphs. In this lab, we will learn how to use tick formatters in Matplotlib.","steps":[{"title":"Importing Matplotlib and setting up the plot","body":["Importing Matplotlib and setting up the plot","First, we need to import the Matplotlib library and set up the plot. We will create an empty plot with one y-axis and one x-axis. We will also configure the axis to only show the bottom spine, set the tick positions, and define the tick length."],"code":[{"lang":"python","text":"import matplotlib.pyplot as plt\nfrom matplotlib import ticker\n\ndef setup(ax, title):\n    \"\"\"Set up common parameters for the Axes in the example.\"\"\"\n    # only show the bottom spine\n    ax.yaxis.set_major_locator(ticker.NullLocator())\n    ax.spines[['left', 'right', 'top']].set_visible(False)\n\n    # define tick positions\n    ax.xaxis.set_major_locator(ticker.MultipleLocator(1.00))\n    ax.xaxis.set_minor_locator(ticker.MultipleLocator(0.25))\n\n    ax.xaxis.set_ticks_position('bottom')\n    ax.tick_params(which='major', width=1.00, length=5)\n    ax.tick_params(which='minor', width=0.75, length=2.5, labelsize=10)\n    ax.set_xlim(0, 5)\n    ax.set_ylim(0, 1)\n    ax.text(0.0, 0.2, title, transform=ax.transAxes,\n            fontsize=14, fontname='Monospace', color='tab:blue')\n\n\nfig, ax = plt.subplots(figsize=(8, 2))\nsetup(ax, \"Tick Formatters\")"}]},{"title":"Simple Formatting","body":["In this step, we will show how to use a simple formatter by passing a string or function to ~.Axis.set_major_formatter or ~.Axis.set_minor_formatter. We will create two plots, one using a string formatter and the other using a function formatter."],"code":[{"lang":"python","text":"fig0, axs0 = plt.subplots(2, 1, figsize=(8, 2))\nfig0.suptitle('Simple Formatting')\n\n# A ``str``, using format string function syntax, can be used directly as a\n# formatter.  The variable ``x`` is the tick value and the variable ``pos`` is\n# tick position.  This creates a StrMethodFormatter automatically.\nsetup(axs0[0], title=\"'{x} km'\")\naxs0[0].xaxis.set_major_formatter('{x} km')\n\n# A function can also be used directly as a formatter. The function must take\n# two arguments: ``x`` for the tick value and ``pos`` for the tick position,\n# and must return a ``str``. This creates a FuncFormatter automatically.\nsetup(axs0[1], title=\"lambda x, pos: str(x-5)\")\naxs0[1].xaxis.set_major_formatter(lambda x, pos: str(x-5))\n\nfig0.tight_layout()"}]},{"title":"Formatter Object Formatting","body":["In this step, we will use .Formatter objects to format the ticks. We will create seven plots, each using a different formatter."],"code":[{"lang":"python","text":"fig1, axs1 = plt.subplots(7, 1, figsize=(8, 6))\nfig1.suptitle('Formatter Object Formatting')\n\n# Null formatter\nsetup(axs1[0], title=\"NullFormatter()\")\naxs1[0].xaxis.set_major_formatter(ticker.NullFormatter())\n\n# StrMethod formatter\nsetup(axs1[1], title=\"StrMethodFormatter('{x:.3f}')\")\naxs1[1].xaxis.set_major_formatter(ticker.StrMethodFormatter(\"{x:.3f}\"))\n\n# FuncFormatter can be used as a decorator\n@ticker.FuncFormatter\ndef major_formatter(x, pos):\n    return f'[{x:.2f}]'\n\nsetup(axs1[2], title='FuncFormatter(\"[{:.2f}]\".format)')\naxs1[2].xaxis.set_major_formatter(major_formatter)\n\n# Fixed formatter\nsetup(axs1[3], title=\"FixedFormatter(['A', 'B', 'C', ...])\")\n# FixedFormatter should only be used together with FixedLocator.\n# Otherwise, one cannot be sure where the labels will end up.\npositions = [0, 1, 2, 3, 4, 5]\nlabels = ['A', 'B', 'C', 'D', 'E', 'F']\naxs1[3].xaxis.set_major_locator(ticker.FixedLocator(positions))\naxs1[3].xaxis.set_major_formatter(ticker.FixedFormatter(labels))\n\n# Scalar formatter\nsetup(axs1[4], title=\"ScalarFormatter()\")\naxs1[4].xaxis.set_major_formatter(ticker.ScalarFormatter(useMathText=True))\n\n# FormatStr formatter\nsetup(axs1[5], title=\"FormatStrFormatter('#%d')\")\naxs1[5].xaxis.set_major_formatter(ticker.FormatStrFormatter(\"#%d\"))\n\n# Percent formatter\nsetup(axs1[6], title=\"PercentFormatter(xmax=5)\")\naxs1[6].xaxis.set_major_formatter(ticker.PercentFormatter(xmax=5))\n\nfig1.tight_layout()"}]},{"title":"Displaying the Plots","body":["Finally, we will display the plots using plt.show()."],"code":[{"lang":"python","text":"plt.show()"}]}],"commands":[],"reference":[],"source":"matplotlib/matplotlib · BSD 3-Clause"},"labex-matplotlib-setting-default-y-axis-tickels-on-the-right":{"intro":"In this tutorial, we will learn how to set the default y-axis tick labels on the right side of the plot using Matplotlib. By default, the y-axis tick labels are placed on the left side of the plot. However, sometimes it might be more suitable to have them on the right side instead.","steps":[{"title":"Import the necessary libraries and modules","body":["Import the necessary libraries and modules","Before we start, we need to import the necessary libraries and modules. In this tutorial, we will be using Matplotlib and NumPy."],"code":[{"lang":"python","text":"import matplotlib.pyplot as plt\nimport numpy as np"}]},{"title":"Set the default y-axis tick labels on the right","body":["Set the default y-axis tick labels on the right","We can set the default y-axis tick labels on the right side of the plot using the following code:"],"code":[{"lang":"python","text":"plt.rcParams['ytick.right'] = plt.rcParams['ytick.labelright'] = True\nplt.rcParams['ytick.left'] = plt.rcParams['ytick.labelleft'] = False"}]},{"title":"Create a sample plot","body":["Let's create a sample plot to see how it looks with the y-axis tick labels on the right side."],"code":[{"lang":"python","text":"x = np.arange(10)\n\nfig, (ax0, ax1) = plt.subplots(2, 1, sharex=True, figsize=(6, 6))\n\nax0.plot(x)\nax0.yaxis.tick_left()\n\nax1.plot(x)\n\nplt.show()"}]},{"title":"Interpret the results","body":["In the resulting plot, we can see that the y-axis tick labels are on the right side instead of the left side. The first plot has the y-axis tick labels on the left side because we specified it using the ax0.yaxis.tick_left() code. The second plot has the y-axis tick labels on the right side because we set the default y-axis tick labels on the right side using the code in Step 2."],"code":[]}],"commands":[],"reference":[],"source":"matplotlib/matplotlib · BSD 3-Clause"}};
